    'cli.doctor.server_ready' => 'pcntl, posix и ffi доступны — `serve` может запуститься',
    'cli.doctor.server_refuses' => '`serve` откажется запускаться: {problems}',
    'cli.doctor.sessions' => 'Сохранено сессий: {count}',
    'cli.doctor.settings_clean' => 'все файлы настроек содержат только ключи, которые читает candy-code',
    'cli.doctor.unknown' => 'неизвестно',
    'cli.headless.permission_hint' => '  подсказка: запуск `-p` без явного режима стартует в запрашивающем режиме `default`; безымянным запросам некому ответить, поэтому они завершаются отказом. Для скриптованных запусков укажите --permission-mode bypass-permissions (или accept-edits), чтобы продолжить.',
    'cli.help.screen' => <<<'TXT'
CandyCode — AI-ассистент для программирования в терминале.

Использование:
  candy-code                       Запустить интерактивный TUI (по умолчанию)
  candy-code <dir>                 Запустить TUI с корнем в <dir>, который должен
                                   существовать (только как первый аргумент)
  candy-code [<dir>] <words…>      Запустить TUI и отправить слова как его
                                   первый запрос, напр. candy-code fix the bug
  candy-code -c                    Продолжить последнюю сессию
  candy-code --resume [<id>]       Возобновить сохранённую сессию (выбор без id)
  candy-code -p <prompt>           Выполнить один запрос и выйти (одноразовый)
  candy-code run "<prompt>"        Алиас для -p "<prompt>" (одноразовый режим)
  candy-code --output-format json  Вывод машиночитаемого JSON (одноразовый)
  candy-code --worktree [<name>]   Выполнить сессию в git worktree
                                   (создаётся, если не существует)

Подкоманды (ни одна не открывает TUI и не требует провайдера, API-ключа или
терминала; каждая отвечает и выходит, кроме serve и mcp serve, которые работают до
остановки — и attach, исключение из обоих правил: запускает TUI на сессии работающего сервера;
acp выполняет ходы для редактора, пока редактор не отключится):
  bundles list           Список плагин-бандлов, видимых из этой директории: имя,
                         версия, уровень и поверхности каждого —
                         включая хуки и .mcp.json, которые candy-code
                         отказывается выполнять.
  bundles install <src>  Скопировать директорию бандла или клонировать git URL
                         с ограничением глубины до одного уровня в корень
                         пользовательских бандлов (~/.candy-code/bundles), где владелец только вы.
  doctor                 Проверить установку и сообщить о каждой найденной
                         проблеме: версия PHP, расширения для хранилища сессий
                         и serve, конфиг-файл, политика разрешений,
                         выбранный провайдер, база данных сессий
                         и конфигурация MCP проекта. Код выхода 1, если любая
                         проверка ПРОВАЛИЛАСЬ.
                         Не путать с вызываемой моделью утилитой "doctor",
                         которая сообщает модели протокол изображений терминала.
  import claude          Предпросмотр импорта настроек Claude Code: читает пользовательский
                         файл настроек Claude и файл .claude в корне запуска
                         при указанном --project, переводит списки
                         allow/deny/ask в permissionRules (строгая сторона
                         всегда побеждает — deny важнее allow), сопоставляет модель и помечает
                         каждый ключ без назначения как skipped. Ничего не записывается до
                         подтверждения: --yes принимает напечатанный предпросмотр без вопросов,
                         без него запрашивается интерактивный терминал. Предпросмотр называет
                         каждое правило allow, которое расширит набор команд без подтверждения.
  login <provider>       Вход в один провайдер: claude-code и codex передают
                         терминал своему CLI (токен никогда не проходит
                         через candy-code); openai, anthropic и gemini
                         вставляют ключ в блок providers файла конфигурации;
                         остальные указывают, кто реально владеет учётными данными.
  models                 Список провайдеров, доступных для выбора в этой установке,
                         и модель по умолчанию для каждого; «*» отмечает
                         выбранный.
  session list [--all|--archived|--children] [--limit N]
                         Список сохранённых сессий, закреплённые первыми, затем
                         по свежести: id, последняя правка, тип, ходы, провайдер/модель
                         и имя (★ отмечает закреплённую строку). --children добавляет
                         строки суб-агентов и фоновых задач, --archived добавляет
                         архивные, --all добавляет оба; 20 строк, если
                         --limit не укажет иначе.
  session show <target>  Вывести детали одной сессии и транскрипт.
  session rename <target> <title…>
                         Переименовать сессию; слова после target —
                         это заголовок.
  session delete <target> [--with-children]
                         Удалить сессию. Суб-агенты удаляются вместе с ней;
                         ветки сохраняются, если не указан --with-children.
  session pin|unpin|archive|unarchive <target>
                         Закрепить сессию (в списке первой, никогда не удаляется) или
                         архивировать (скрыта из списка по умолчанию, сохранена).
                         <target> — id, имя или уникальный префикс id.
                         Код выхода 1, если ничего не найдено, 2, если префикс
                         неоднозначен (кандидаты перечислены).
  mcp list               Список MCP-серверов, объявленных в .mcp.json, БЕЗ
                         запуска какого-либо из них. Сообщает, если файл
                         отсутствует, разрешается вне дерева проекта или
                         присутствует, но корень проекта не доверенный.
  mcp trust              Одобрить .mcp.json этого проекта как есть: добавить
                         корень в "trustedProjectMcp" и записать команду,
                         аргументы и env каждого сервера, чтобы последующее изменение
                         любого из них было отклонено при запуске до повторного одобрения.
                         Ничего не запускает.
  mcp import claude|opencode|claude-project <path> [--write user]
                         Перевести чужую MCP-конфигурацию и напечатать
                         эквивалентный блок .mcp.json в stdout. Только печать
                         по умолчанию; --write user добавляет переведённые
                         записи в ~/.candy-code/mcp.json пользователя
                         (коллизия имён отклоняет всю запись, а
                         проектный уровень никогда не записывается). Переименования,
                         сделанные переводом, перечислены в stderr.
  mcp serve [--root PATH]
                         Обслуживать candy-code как MCP-сервер через stdio:
                         один кадр JSON-RPC на строку на входе, один ответ на строку
                         на выходе, пока stdin не закрыт. Вызовы инструментов выполняют
                         набор только для чтения (Read, Glob, Grep, Ls, RepoMap), запертый в
                         корень рабочего пространства, через PermissionGate запуска
                         и цепочку хуков PreToolUse — это MCP-сервер,
                         который клиент может запустить; WebSocket
                         `candy-code serve` по-прежнему не говорит по MCP. Работает до
                         остановки.
  lsp install <language> Установить закреплённый языковой сервер для одного
                         языка: npm-пакет или бинарник релиза с проверкой контрольной суммы,
                         в приватный корень установки в домашней директории.
                         `lsp list` отвечает, какие языки доступны для установки.
                         installable.
  lsp list               Отчёт по каждому устанавливаемому языку: закреплённая
                         версия, где установлен сервер (или что не установлен),
                         и существует ли релиз для ОС и архитектуры
                         этой машины. Ничего не запускает,
                         ничего не скачивает.
  self-update [--check] [--rollback] [--allow-unsigned] [--channel=stable|dev]
                         Заменить эту phar-установку последним опубликованным
                         релизом candy-code, sha256-проверенным по
                         sidecar релиза ДО замены; работающий phar
                         сохраняется как <phar>.old, и --rollback восстанавливает ровно
                         эту копию один раз. Когда публичный ключ подписи закреплён
                         в источнике релиза, подпись candy-code.phar.minisig
                         тоже должна пройти проверку (--allow-unsigned пропускает
                         только эту проверку). --check лишь сообщает текущую vs
                         последнюю версию и выходит с кодом 1, когда доступно обновление. A
                         Composer-установка отклоняется громко, с указанием
                         команды composer update для запуска вместо этого. Сборка из
                         исходников следует за rolling-релизом candy-code/dev
                         по умолчанию (актуальна, когда целевой коммит
                         релиза совпадает с sha в штампе), а --channel
                         явно выбирает одну из веток.
  serve [--host <ip>] [--port <n>] [--allow-remote] [--allowed-host <list>]
        [--allowed-ips <list>] [--allowed-origin <list>] [--allow-dir-browse]
        [--browse-root <dir>] [--web-root <dir>] [--no-web] [--allow-bypass]
        [--allow-root] [--detach] [--parent-pid <pid>]
        [--tls-cert <file>] [--tls-key <file>]
                         Запуск WebSocket + HTTP-сервера, с которым общается
                         веб-интерфейс, в foreground до Ctrl+C. По умолчанию
                         привязывается к 127.0.0.1:7420 и выводит URL входа,
                         одноразовый код из которого обменивается на cookie
                         браузера; он нужен каждому клиенту, как и токен в
                         ~/.candy-code/server/token, включая loopback. Параметры:
      --host <ip>        Адрес для привязки (по умолчанию 127.0.0.1; localhost
                         и ::1 тоже считаются loopback). Любой другой адрес
                         отклоняется, если не указан также --allow-remote.
      --port <n>         Порт для привязки (по умолчанию 7420; 0 — свободный).
      --allow-remote     Разрешить не-loopback --host. Без --tls-cert и
                         --tls-key это plain HTTP: поставьте TLS reverse proxy
                         перед ним или раздавайте TLS напрямую (см. ниже). На
                         0.0.0.0 или :: сервер отвечает на собственные адреса
                         машины, и URL входа их перечисляет.
      --tls-cert <file>  PEM-сертификат, с которым слушатель сам раздаёт TLS,
                         указывается вместе с --tls-key. URL входа тогда
                         начинается с https://, cookie сессии несёт Secure,
                         а plain http:// клиент не получает никакого ответа.
      --tls-key <file>   PEM-приватный ключ для --tls-cert: читаемый файл без
                         group/world битов, соответствующий сертификату.
                         Неверная или неполная пара отклоняется при запуске.
      --allowed-host <list>
                         Дополнительные имена хостов (или host:port),
                         разделённые запятыми, на которые сервер отвечает,
                         например DNS-имя этой машины. Повторяемый.
      --allowed-ips <list>
                         IP-адреса клиентов или CIDR-диапазоны (напр.
                         1.2.3.4,10.0.0.0/8), разделённые запятыми, которым
                         разрешено подключаться; любой другой адрес получает
                         403 до входа. Loopback всегда разрешён. Не задан:
                         фильтрация по адресу отсутствует. Повторяемый.
      --allowed-origin <list>
                         Дополнительные браузерные origins
                         (http(s)://host[:port]), разделённые запятыми,
                         помимо собственного. Повторяемый.
      --allow-dir-browse Разрешить авторизованным клиентам выбирать каталог
                         для новой сессии: они могут просматривать имена
                         каталогов (не файлов) внутри --browse-root. Выкл.
      --browse-root <dir>
                         Каталог, в котором ограничено --allow-dir-browse
                         (по умолчанию домашний каталог).
      --web-root <dir>   Раздавать веб-интерфейс из <dir> вместо пакета
                         sugarcraft/candy-code-web.
      --no-web           Раздавать только API и WebSocket, без файлов UI.
      --allow-bypass     Разрешить сессиям работать в режиме bypass-permissions
                         или dont-ask (по умолчанию запрещено; сессии сервера
                         стартуют в default, если --permission-mode не укажет
                         иное).
      --allow-root       Разрешить запуск от root (по умолчанию запрещено).
      --detach           Запуск в фоне: вывести URL и pid после привязки
                         порта, затем выйти; сервер пишет лог в server.log
                         в своём state-каталоге.
      --parent-pid <pid> Остановить сервер при завершении процесса <pid>
                         (для редактора или TUI, запускающего приватный
                         сервер). Отказывается запускаться без ext-pcntl,
                         ext-posix и ext-ffi (см. doctor). Код 1, если порт
                         занят или сервер уже работает из того же state-каталога.
  serve status           Отчёт о работающем сервере: pid, URL, root, uptime
                         и отвечает ли GET /api/health. Код 1, если сервер
                         не запущен.
  serve stop [--force]   Остановить: SIGTERM, до 30 с на drain, затем SIGKILL.
      --force            SIGKILL сразу.
  serve logs [-f]        Вывести конец лога отсоединённого сервера.
  -f, --follow           Продолжать выводить новые строки до остановки.
  serve url [--qr]       Вывести URL входа со свежим одноразовым кодом.
      --qr              Отобразить каждый URL входа как сканируемый QR-код
                         в терминале.
  serve token [--rotate] Вывести owner-токен, который отправляют bearer-клиенты.
      --rotate           Заменить его; работающий сервер хранит старый до
                         перезапуска.
  attach [<session>] [--url <url>]
                         Запуск TUI на сессии работающего candy-code serve:
                         сервер выполняет каждый ход и его инструменты, а
                         этот терминал показывает их и отвечает на вопросы
                         о разрешениях. <session> — id, имя или уникальный
                         префикс id одной из сессий сервера; без него
                         создаётся новая. Сервер тот, о котором сообщает
                         serve status, его токен берётся из
                         CANDY_CODE_SERVER_TOKEN или token-файла
                         state-каталога. Выход отсоединяет; выполняющийся
                         ход продолжается. Код 1, если сервер не отвечает.
      --url <url>        Подключиться к серверу по <url> (адрес, который
                         выводит serve) вместо стандартного.
  acp                    Запуск как агент Agent Client Protocol: редактор
                         корень проекта редактора, запуски здесь используют
                         провайдера и инструменты этой установки, а редактор
                         отвечает на их вопросы о разрешениях. Не для терминала: stdout
                         несёт только протокол (всё остальное идёт в
                         stderr). Выход 0, когда редактор закрывает stdin.
  completion bash|zsh|fish
                         Записать скрипт автодополнения для оболочки в stdout, напр.
                         eval "$(candy-code completion bash)".
  usage [7|30|all] [--session <target>]
                         Свести постоянный реестр расходов по дням и моделям:
                         та же страница, что печатает `/usage`, по тому же общему
                         своду. 7 и 30 берут целые дни UTC, включая сегодня,
                         all (или без операнда) охватывает весь реестр, а
                         окно вне этого набора отклоняется, а не
                         расширяется молча. --session сужает до одной сессии
                         по id, имени или уникальному префиксу; --output-format json
                         выдаёт карту фактов, из которой построена страница. Нечитаемый
                         реестр сообщает причину и выходит с кодом 1;
                         доллары для сводов, включающих неценованную модель
                         печатаются как нижняя граница ≥, никогда как обычная сумма.

Параметры:
  -p, --prompt <text>    Задать промпт в командной строке (одноразовый режим)
      --output-format <format>
                         Формат вывода: "text" (по умолчанию), "json" или
                         "stream-json" (события NDJSON, ответ последним)
      --root <dir>       Использовать <dir> как корень проекта вместо текущего
                         каталога. Также принимает --root=<dir> (форму, которую
                         следует использовать, если <dir> начинается с "-"); её нельзя опустить.
                         Указание корня здесь И как позиционного аргумента
                         отклоняется, а не молча выбирается одно.
      --config <file>    Читать настройки, разрешения и доверенные корни хуков из
                         <file> вместо ~/.candy-code/config.json. Также
                         принимает --config=<file>. Файл должен существовать,
                         быть читаемым, принадлежать вам, и ни он, ни его
                         каталог не должны быть world-writable — он несёт
                         политику разрешений, поэтому к нему тот же стандарт,
                         что и к ~/.candy-code/config.json (файл в /etc или
                         /tmp обычно отклоняется по одной из этих причин).
                         Перемещается только ФАЙЛ: агенты, скиллы, воркфлоу,
                         сессии и память остаются в ~/.candy-code.
      --model <name>     Использовать <name> как модель диалога, переопределяя
                         $CANDY_CODE_MODEL и дефолт провайдера. Также
                         принимает --model=<name>. Выбирает модель, а не провайдер
                         — провайдер по-прежнему берётся из $CANDY_CODE_PROVIDER или
                         сохранённой настройки `provider`, и это
                         независимые оси.
      --permission-mode <mode>
                         Работать в <mode> вместо режима из файла
                         конфигурации. Также принимает --permission-mode=<mode>. Наивысший
                         приоритет: перебивает $CANDY_CODE_PERMISSION_MODE и
                         ключ permissionMode в конфиге. Один из: default,
                         accept-edits, plan, auto, dont-ask,
                         bypass-permissions. Без установки TUI и -p
                         стартуют в default (спрашивает перед записями и shell-
                         командами); только локально запущенный демон стартует в
                         bypass-permissions.
      --max-cost <usd>   Ограничить этот запуск <usd> долларами США заявленных
                         расходов: ход, который пересёк бы потолок,
                         отклоняется и не отправляется. Также принимает --max-cost=<usd>.
                         Наивысший приоритет: перебивает $CANDY_CODE_MAX_COST и
                         ключ maxCostUsd в конфиге. Дробные допустимы,
                         ведущий $ принимается ($2.50); ноль и отрицательные
                         отклоняются, а не читаются как «без лимита». /budget по-прежнему
                         повышает или снимает лимит для текущей сессии.
      --max-turns <n>    Ограничить этот запуск <n> шагами цикла инструментов: ход,
                         который использует все, останавливается на месте и сообщает об этом.
                         Также принимает --max-turns=<n>. Наивысший приоритет:
                         перебивает ключ настройки maxToolSteps (эта ось
                         не имеет переменной окружения). Положительное целое
                         число; ноль отклоняется, а не читается как «без
                         лимита», а непригодное значение отклоняет запуск,
                         а не молча уступает настройке.
      --json-schema <path-or-json>
                         Ограничить ответ JSON-схемой: встроенный
                         документ {"type":"object",...} или путь к файлу,
                         содержащему его. Также принимает --json-schema=<value>;
                         форма с = — та, которую следует использовать, если путь начинается
                         с "-". Только провайдеры, заявляющие поддержку
                         ответов, ограниченных схемой, выполняют запрос вообще
                         — остальные отклоняют с кодом 2, а не
                         тарифицируют неограниченный ответ. Схема
                         гейтит запрос само-завершения хода; шаги,
                         продолжающие цикл инструментов, остаются свободными (принудительный
                         JSON-ответ не может содержать вызовы инструментов).
      --append-system-prompt <text-or-@file>
                         Добавить правила оператора к системному промпту
                         этого единственного запуска: встроенный текст или @path к файлу,
                         содержащему их. Также принимает --append-system-prompt=<value>;
                         форма с = — та, которую следует использовать, если путь начинается
                         с "-". Правила приходят как ещё один fenced
                         блок личных инструкций, никогда не переопределение: они
                         не могут заменить или понизить слои выше, и
                         поддельные маркеры блоков в тексте нейтрализуются.
                         Ограничены тем же размером, что и документ инструкций.
                         Только с -p или глаголом run: запуск без
                         промпта для добавления отклоняется с кодом 2, а не
                         молча игнорирует заданные правила.
  -c, --continue         Повторно открыть последнюю использованную сессию, транскрипт
                         и всё остальное, вместо создания новой. Без этого
                         каждый запуск открывает новую сессию; Up в пустом
                         поле ввода по-прежнему вызывает промпты из предыдущих.
      --resume [<id|name>]
                         Повторно открыть сохранённую сессию по id, уникальному префиксу id или
                         имени (см. `session list`). Без значения — открыть
                         выбор сессии при запуске; рядом с -p цель ОБЯЗАТЕЛЬНА
                         (транскрипт заполняет одноразовый запрос, а
                         ответ сохраняется обратно в строку). Также принимает
                         --resume=<id>. Не совместимо с --continue.
      --worktree [<name>]
                         Выполнить всю сессию внутри git worktree
                         main-<name> на ветке candy-code/<name>, создаётся
                         при первом использовании; без имени worktree получает
                         автоматически выбранное. При выходе worktree без
                         коммитов и без правок удаляется; тот, в котором
                         есть работа, остаётся и сообщает свой путь. Отклоняется
                         вне git work tree и рядом с `serve`.
      --incognito        Запуск, который ничего не сохраняет: ни строки сессии, ни
                         транскрипта, ни автоматических записей памяти в конце хода.
                         Результат run живёт только в процессе;
                         сессии и заметки, сохранённые РАНЕЕ, остаются читаемыми.
                         Отклоняется рядом с --continue или --resume, которые повторно
                         открывают сохранённые сессии.
      --restricted       Запуск, который не может выполнять код: Bash, PtyRun, Task,
                         Workflow, ShellStop и mcp_call исключаются из
                         всех наборов для модели на всю сессию, и
                         /permissions не может вернуть их. Файловые инструменты остаются,
                         в рамках существующего ограничения путей. Также принимает
                         --restricted=true|false, чтобы обёртка могла переопределить
                         алиас с голым флагом. Сохраняется при перезапуске.
      --safe-mode        Запуск, игнорирующий всё доверие: каждый доверенный
                         корень проекта отвечает как недоверенный (хуки, проектный
                         MCP и командные шеллы), бандлы не загружаются, и
                         чужие скиллы, команды или агенты не обнаруживаются.
                         Нативные настройки, скиллы и команды остаются. Также
                         принимает --safe-mode=true|false для переопределения
                         алиаса. Сохраняется при перезапуске.
  -h, --help             Показать это справочное сообщение
  -v, --version          Показать установленную версию и выйти
      --                 Конец опций: каждый последующий аргумент позиционный,
                         никогда не флаг

Переменные окружения:
   CANDY_CODE_PROVIDER    Провайдер для использования: openai, anthropic, claude-code,
                          sglang, bedrock, vertex, custom
   CANDY_CODE_MODEL       Имя модели (переопределяет значение по умолчанию провайдера; --model имеет приоритет)
   CANDY_CODE_PERMISSION_MODE
                          Режим разрешений для старта, переопределяет
                          ключ конфигурации permissionMode (--permission-mode имеет приоритет)
   CANDY_CODE_BACKEND_CMD Команда шелла для пользовательского адаптера бэкенда, по контракту
                          PROSE: получает JSON-историю на stdin, пишет
                          текст ответа на stdout, который используется дословно
                          (обрезается только с двух сторон, так что каждый перевод строки, пустая
                          строка и отступ внутри сохраняются).
   CANDY_CODE_BACKEND_CMD_STREAM
                          Тот же вызов шелла по другому контракту, ПОТОК
                          ТОКЕНОВ: один токен на строку, перевод строки между двумя
                          токенами — это фрейминг и отбрасывается, а ПУСТАЯ строка —
                          литеральный перевод строки в ответе. Колбэк срабатывает на каждый
                          токен по мере их генерации командой, но цикл чтения
                          синхронный, поэтому экран перерисовывается один раз в конце,
                          а не токен за токеном. Не взаимозаменяем с
                          CANDY_CODE_BACKEND_CMD ни в одном направлении — проза
                          обёртка, прогнанная через эту переменную, вернётся без каждого
                          перевода строки, а каждая пустая строка схлопнется в одну.
                          CANDY_CODE_BACKEND_CMD имеет приоритет, когда заданы обе.
                          Для обеих: не задана, пуста и только пробелы — всё
                          считается отсутствующим.
   CANDY_CODE_DISABLE_PARALLEL_TOOL_CALLS
                          Выполнять вызовы инструментов за ход строго по одному.
                          Конкурентная отправка — значение по умолчанию и всегда
                          группирует только немодифицирующие инструменты; это аварийный выход.
                          Сохраните как "parallelToolCalls": false в
                          ~/.candy-code/config.json.
   CANDY_CODE_PARALLEL_TOOL_DEADLINE
                          Секунды, в течение которых одна конкурентная группа может работать, прежде чем
                          отстающие будут убиты и сообщены как неудачные вызовы
                          (по умолчанию 90, должно быть 1-119; дробная часть отбрасывается).
                          Сохраните как "parallelToolDeadlineSeconds".
                          Приоритет: эта переменная, затем сохранённый ключ,
                          затем значение по умолчанию. Значение вне диапазона 1-119 или то,
                          которое вообще не является числом, не считается установленным —
                          оно переходит к следующему источнику, а не
                          отбрасывается.
   CANDY_CODE_ADVISOR_MODEL
                          Модель, к которой обращается инструмент `Advisor` за вторым
                          мнением: завершение без инструментов, тарифицируемое как
                          любой другой вызов. В отличие от CANDY_CODE_TITLE_MODEL,
                          здесь нет дешёвой замены — не задано означает, что инструмент
                          не предлагается вовсе. Считывается при запуске.
   CANDY_CODE_TITLE_MODEL Дешёвая модель для автоименования сессии после
                          первого обмена; по умолчанию — модель провайдера.
   CANDY_CODE_SUMMARY_MODEL
                          Модель, создающая сводки компактирования;
                          по умолчанию — модель текущего диалога, что позволяет
                          переиспользовать кэш промптов.
   CANDY_CODE_CONTEXT_PRUNING
                          auto, manual или off: как сессия усекает свой
                          контекст, когда /pruning не выбрал (по умолчанию auto).
   CANDY_CODE_MAX_COST    Лимит расходов на этот запуск, в долларах США
                          (допустимы дроби; ведущий "$" принимается;
                          --max-cost приоритетнее). Оборот, превышающий лимит,
                          отклоняется.
   CANDY_CODE_CONNECT_TIMEOUT
                          Ограничение фазы подключения, в секундах (допустимы
                          дроби; по умолчанию 15.0) для HTTP-транспортов
                          провайдера. Ограничивает только установку соединения
                          — это не общий таймаут запроса. Сколько
                          может занимать подключённому стриминговому серверу
                          отправка заголовков ответа — отдельный
                          параметр streamHeaderTimeoutSeconds.
   CANDY_CODE_SEARCH_ENDPOINT
                          API поиска, к которому обращается встроенный инструмент WebSearch.
   CANDY_CODE_SESSION_RETENTION_DAYS
                          Положительное целое число дней: каждый запуск удаляет
                          сессии, не тронутые дольше этого срока.
   CANDY_CODE_SHARE_UPLOAD_URL
                          Устаревший хост загрузки: /share никогда не загружает
                          ничего. Если задан, локальный экспорт всё равно
                          создаётся, а ответ явно отвергает ключ и указывает
                          на /share serve, который публикует self-hosted
                          страницу снимка на вашем собственном candy-code serve.
   CANDY_CODE_WORKTREES_DIR
                          Базовый каталог, в котором создаются git
                          worktrees для каждого тиммейта.
   CANDY_CODE_DISABLE_MOUSE
                          Любое значение, кроме пустого или 0, полностью отключает
                          отслеживание мыши.
   CANDY_CODE_DISABLE_MOUSE_CLICKS
                          Любое значение, кроме пустого или 0, игнорирует
                          клики, сохраняя прокрутку колесом.
   CANDY_CODE_DISABLE_PROMPT_CACHE
                          Любое значение, кроме пустого или 0, отключает
                          точки кэширования промптов провайдера.
   CANDY_CODE_DISABLE_PROMPT_SUGGESTIONS
                          Любое значение, кроме пустого или 0, отключает
                          подсказку следующего сообщения (→ принимает) после каждого оборота.
   CANDY_CODE_DISABLE_AUTO_MEMORY
                          Любое значение, кроме пустого или 0, отключает автопамять:
                          сохранение устойчивых фактов как заметок после оборота и
                          проход «сна», сворачивающий журнал компактирования
                          в них.
   CANDY_CODE_DISABLE_MODEL_METADATA
                          Любое значение, кроме пустого или 0, отключает чтение и
                          обновление базы моделей LiteLLM, определяющей размеры и
                          цены моделей без встроенных данных.
   CANDY_CODE_NO_UPDATE_CHECK
                          Любое значение, кроме пустого или 0, отключает ежедневную
                          проверку релизов phar и уведомление об обновлении при запуске;
                          запросы не покидают процесс, а устаревшее кэшированное
                          уведомление больше не отображается.
   CANDY_CODE_DISABLE_SYMBOL_MAP
                          Любое значение, кроме пустого или 0, исключает ранжированную
                          карту символов из системного промпта.
   CANDY_CODE_BACKGROUND  light или dark — задаёт то, что адаптивная тема
                          считает о фоне терминала, пропуская
                          зонд OSC 11 и COLORFGBG.
   CANDY_CODE_DEBUG_SKILLS
                          Любое значение, кроме пустого или 0, выводит строки
                          SkillLoader о каждом пропуске и отказе по каталогу
                          обратно в stderr.
   CANDY_CODE_DEBUG_COMMANDS
                          Любое значение, кроме пустого или 0, выводит строки
                          CommandLoader об отказе в обнаружении обратно в stderr.
   CANDY_CODE_DEBUG_RULES Любое значение, кроме пустого или 0, выводит строки
                          RuleLoader об отказе в обнаружении обратно в stderr.
   CANDY_CODE_DEBUG_STREAM
                          Любое значение, кроме пустого или 0, оставляет строку
                          Chat «onToken observer threw» в stderr.
                          Само отсоединение происходит в любом случае.
   CANDY_CODE_SERVER_HOST Адрес, к которому привязывается `serve` (--host имеет приоритет).
   CANDY_CODE_SERVER_PORT Порт, к которому привязывается `serve` (--port имеет приоритет).
   CANDY_CODE_SERVER_ALLOWED_ORIGINS
                          Дополнительные разделённые запятой origins, которые принимает `serve`
                          (--allowed-origin имеет приоритет).
   CANDY_CODE_SERVER_ALLOWED_HOSTS
                          Дополнительные разделённые запятой имена хостов, на которые отвечает `serve`
                          (--allowed-host имеет приоритет).
   CANDY_CODE_SERVER_ALLOWED_IPS
                          Разделённые запятой IP-адреса или CIDR клиентов, которых `serve` допускает
                          помимо loopback (--allowed-ips имеет приоритет).
   CANDY_CODE_SERVER_WEB_ROOT
                          Каталог, из которого `serve` раздаёт веб-интерфейс (--web-root
                          имеет приоритет).
   CANDY_CODE_SERVER_TOKEN
                          Токен, который требует `serve`, вместо токена в
                          его каталоге состояния (не менее 32 символов; для
                          контейнеров).
   CANDY_CODE_SERVER_DIR  Каталог, в котором `serve` хранит токен, блокировку,
                          запись обнаружения и журнал (по умолчанию
                          ~/.candy-code/server; создаётся с правами 0700).
   CANDY_CODE_SERVER_PARENT_PID
                          Процесс, вместе с которым `serve` завершается (--parent-pid имеет приоритет).
   CANDY_CODE_MCP_DISABLE
                          1, true или yes (без учёта регистра) полностью отключают
                          MCP проекта: .mcp.json считается отсутствующим, ни один
                          сервер не запускается. Не задано, 0 или любое другое значение
                          оставляет MCP включённым — в отличие от переменных-флагов,
                          учитываются только эти три слова.
   CANDY_CODE_QUIET_LOGS  1, true или yes (без учёта регистра) заглушают
                          побочный канал error_log() на уровне процесса в его единственном
                          приёмнике; не задано, 0 или любое другое значение
                          оставляет диагностику активной. Только при запуске, без ключа настроек.
   CANDY_CODE_REDUCED_MOTION
                          1, true или yes (без учёта регистра) фиксируют
                          спиннер агента на одном статичном кадре — для пользователей
                          с повышенной чувствительностью к движению. Считывается один раз при запуске;
                          ключа в настройках нет.
   CANDY_CODE_SD_BASE_URL Базовый URL сервера Stable
                          Diffusion в стиле A1111 (sdapi), к которому обращается
                          медиатранспорт. Приоритет: явное переопределение в коде, затем эта
                          переменная, затем настройка sd.baseUrl.
   CANDY_CODE_MEDIA_RENDER_MODE
                          Способ отрисовки сгенерированных изображений в терминале
                          (слой окружения настройки ui.imageRenderMode; см.
                          docs/ENVIRONMENT.md для допустимых значений).
   CANDY_CODE_ALLOW_ROOT_TESTS
                          Установите ровно 1, чтобы тестовому набору candy-code
                          разрешить запуск от root; не задано или любое другое значение — набор
                          отказывается запускаться при euid 0. Ничего в
                          запуске candy-code не меняется — набор тестов не является
                          пользовательским интерфейсом.
   CANDY_CODE_TOOL_INPUT  Полная карта аргументов текущего вызова инструмента-
                          скрипта пользователя, закодированная в JSON, экспортируется в дочерний
                          процесс каждого запуска инструмента из ~/.candy-code/tools;
                          приложение записывает её, никогда не читает обратно, и
                          никто не устанавливает её вручную.
   CANDY_CODE_OTEL_BATCH_SIZE
                          Количество спанов в одном пакете экспорта OTLP
                          (по умолчанию 64, ограничено 1..2048).
   CANDY_CODE_OTEL_TIMEOUT
                          Секунды, которые может занимать каждая попытка экспорта OTLP
                          (по умолчанию 3; неположительное или некорректное значение
                          откатывается к значению по умолчанию).

   docs/ENVIRONMENT.md содержит таблицу всех переменных, которые читает эта сборка, с их
   полными контрактами.

Коды выхода (одноразовый режим и все подкоманды):
  0                      Запрос выполнен и получен ответ, либо
                         подкоманда выполнилась
  1                      Выполнено с ошибкой: бэкенд выбросил исключение (недоступный хост,
                         отклонённый ключ, ошибка модели) — повтор может помочь — или
                         подкоманда выполнилась с ошибкой (проверка doctor вернула
                         FAIL, глагол `session` не нашёл такую сессию,
                         доверенный .mcp.json не удалось разобрать)
  2                      Ошибка использования или конфигурации, ничего не предпринято
                         и повтор не поможет: запрос не задан,
                         нераспознанный флаг, аргумент без флага, указывающий на
                         несуществующий каталог (для запроса нужен -p), --root
                         указывает на несуществующий каталог, отсутствует
                         composer autoload.php, или выбранный провайдер
                         не может быть создан — либо
                         $CANDY_CODE_PROVIDER, либо провайдер, сохранённый в
                         ~/.candy-code/config.json через Ctrl+P "Switch model".
                         Одноразовый запуск никогда не откатывается к офлайн-провайдеру echo
                         при явно выбранном провайдере.
                         Подкоманда с отсутствующим или неизвестным операндом
                         (`session`, `mcp bogus`, `completion tcsh`) сообщает
                         об этом здесь же.
  130/143/129             TUI: сигнал остановил цикл — 128+N для
                         SIGINT (Ctrl+C), SIGTERM, SIGHUP; кооперативный
                         выход (/exit, q) по-прежнему завершает с 0.

Примеры:
  candy-code -p "Объясни разницу между require и include"
  CANDY_CODE_PROVIDER=anthropic CANDY_CODE_MODEL=claude-sonnet-4-20250514 \
    candy-code -p "Напиши hello world на Go"
  candy-code run "Напиши hello world на Go"
  candy-code doctor
  candy-code models --output-format json | jq '.result.providers'
  eval "$(candy-code completion bash)"
  candy-code serve --port 7420

Дополнительная информация — в README:
  https://github.com/detain/sugarcraft/tree/master/candy-code

