    'cli.noninteractive.provider_remedy_config' => 'удалите запись `provider` из {path} — сохранённый выбор Ctrl+P `Switch model`, из которого этот запуск его взял — чтобы явно выбрать резервный вариант',
    'cli.noninteractive.provider_remedy_env' => 'снимите CANDY_CODE_PROVIDER, чтобы явно выбрать резервный вариант',
    'cli.noninteractive.provider_unusable' => 'провайдер \'{provider}\' недоступен: {error}',
    'cli.noninteractive.refusal' => '[{kind}] {tool} не выполнен - {reason}',
    'cli.noninteractive.session_end_hook_refused' => 'Хук SessionEnd `{hook}` отклонён: {reason}',
    'cli.noninteractive.session_end_refused' => 'Хук SessionEnd отклонён: {reason}',
    'cli.noninteractive.session_funnel_failed' => 'хранилище сессий не удалось открыть для этого запуска; ответ без сохранённой истории, ничего не будет сохранено: {error}',
    'cli.noninteractive.session_save_failed' => 'хранилище сессий не смогло сохранить этот ответ; ответ завершён, код выхода не изменился: {error}',
    'cli.noninteractive.stdin_silent' => 'stdin молчал {seconds} с и был расценён как отсутствие канального контекста; закройте fd 0 или подайте данные до первого байта при медленном запуске',
    'cli.noninteractive.stdin_truncated' => 'канальный stdin превышает лимит 10 МБ; усечение.',
    'cli.noninteractive.turn_hook_blocked' => 'хук хода отклонил этот промпт, он не был отправлен: {reason}',
    'cli.permission.arguments_truncated' => '… (усечено — ещё {bytes} байт НЕ показано)',
    'cli.permission.confirm' => 'Выполнить? [y/N] ',
    'cli.permission.no_tty' => 'вызов инструмента требует вашего разрешения, но stdin не является терминалом — спрашивать некого, отказ.',
    'cli.permission.no_tty_remedy' => <<<'TXT'
  Запустите из терминала, чтобы получить запрос, или задайте политику, которая решает
  без вопросов: --permission-mode <mode> (bypass-permissions выполняет всё),
  или запись permissionRules для {tool} в .candy-code/config.json.
TXT,
    'cli.permission.question' => 'вызов инструмента требует вашего разрешения.',
    'cli.permission.refused' => 'отклонён {tool}.',
    'cli.permission.stdin_ended' => 'stdin закрылся до ответа на вопрос — отказ {tool}.',
    'cli.permission.unrenderable_arguments' => '<аргументы не удалось отобразить>',
    'cli.references.missing' => 'запись `references` {path} не является существующим каталогом, Read, Grep, Glob и Ls не будут к нему обращаться.',
    'cli.references.redundant' => 'запись `references` {path} находится внутри рабочего пространства сессии — песочница уже покрывает её, второй корень чтения не добавляется.',
    'cli.references.unusable' => 'запись `references` не удалось прочитать — это должен быть объект с `path` (или строка пути); запись пропущена.',
    'cli.refuse.bad_mode' => '{source} = \'{value}\', это не режим разрешений (ожидался один из: {valid}). Отказ от запуска вместо перехода к разрешительному значению по умолчанию.',
    'cli.refuse.claude_mcp_arg_entry' => 'claudeMcpArgs содержит не-скалярную запись; только строки argv',
    'cli.refuse.claude_mcp_args' => 'claudeMcpArgs должен быть JSON-массивом скаляров в конфигурации пользователя',
    'cli.refuse.claude_mcp_binary' => 'claudeMcpBinary должен быть строковым путём в конфигурации пользователя',
    'cli.refuse.claude_mcp_env' => 'claudeMcpEnv должен быть объектом JSON в конфигурации пользователя',
    'cli.refuse.claude_mcp_env_entry' => 'claudeMcpEnv должен сопоставлять строковые ключи со строковыми значениями',
    'cli.refuse.config_bom' => 'файл начинается с метки порядка байтов UTF-8, которую JSON не допускает — пересохраните файл как UTF-8 без BOM',
    'cli.refuse.config_dangling' => '{path} существует, но не является читаемым файлом (символическая ссылка не разрешается в файл). Отказ от запуска вместо работы с неизвестной политикой разрешений.',
    'cli.refuse.config_is_directory' => '{path} существует, но не является читаемым файлом (это каталог). Отказ от запуска вместо работы с неизвестной политикой разрешений.',
    'cli.refuse.config_not_json' => '{path} не является допустимым JSON ({error}). Отказ от запуска вместо работы с неизвестной политикой разрешений.',
    'cli.refuse.config_not_object' => 'верхний уровень не является объектом JSON',
    'cli.refuse.config_unreachable' => '{path} недоступен: {reason}, поэтому невозможно узнать, настроена ли там политика разрешений. Отказ от запуска вместо работы с неизвестной политикой разрешений.',
    'cli.refuse.config_unreadable' => '{path} существует, но не читается (проверьте права доступа). Отказ от запуска вместо работы с неизвестной политикой разрешений.',
    'cli.refuse.dangling_directory' => '{dir} — символьная ссылка, не указывающая на каталог, доступный для поиска этому процессу',
    'cli.refuse.foreign_owner' => '{path} принадлежит uid {uid}, а не учётной записи, от имени которой запущена эта сессия, поэтому политика разрешений и цепочка хуков в нём — чужие. Отказ от запуска вместо работы с политикой другой учётной записи.',
    'cli.refuse.hook_chain' => '{error} Отказ от запуска вместо работы с цепочкой хуков, отличной от настроенной.',
    'cli.refuse.hooks_unreachable' => '{path} недоступен: {reason}, поэтому невозможно узнать, настроены ли там хуки. Отказ от запуска вместо работы с неизвестной цепочкой хуков.',
    'cli.refuse.keybindings' => 'параметр keybindings непригоден: {reason}. Удалите ключ, чтобы работать со встроенными привязками (они перечислены в справке /keys). Отказ от запуска вместо работы с переопределениями клавиш, которые вы не запрашивали.',
    'cli.refuse.max_cost_env' => '$CANDY_CODE_MAX_COST = \'{value}\' — это не лимит расходов. Ожидается положительное число долларов США (допустимы дробные значения и ведущий $), например 5 или $2.50. Ноль и отрицательные значения отвергаются, а не трактуются как «без лимита», поскольку это противоположный запрос; слишком большое для представления число (1e309, т. е. бесконечность) отвергается, так как установило бы лимит, который никогда не срабатывает. Снимите переменную для отмены лимита. Отказ от запуска вместо работы без лимита с запрошенным вами потолком.',
    'cli.refuse.max_cost_flag' => '--max-cost = \'{value}\' — это не лимит расходов. Ожидается положительное число долларов США (допустимы дробные значения и ведущий $), например 5 или $2.50. Ноль и отрицательные значения отвергаются, а не трактуются как «без лимита», поскольку это противоположный запрос; слишком большое для представления число (1e309, т. е. бесконечность) отвергается, так как установило бы лимит, который никогда не срабатывает. Уберите флаг для отмены лимита. Отказ от запуска вместо работы без лимита с запрошенным вами потолком.',
    'cli.refuse.max_cost_setting' => 'maxCostUsd в ваших настройках = {value} — это не лимит расходов. Ожидается положительное число долларов США, например 5 или 2.5. Удалите ключ для отмены лимита. Отказ от запуска вместо работы без лимита с запрошенным вами потолком.',
    'cli.refuse.max_turns_flag' => '--max-turns = \'{value}\' — это не лимит шагов. Ожидается положительное целое число шагов цикла инструментов, например 8. Ноль отвергается, а не трактуется как «без лимита», поскольку это противоположный запрос; слишком большое для представления число отвергается, так как установило бы лимит, который никогда не срабатывает. Уберите флаг, чтобы использовать настройку maxToolSteps. Отказ от запуска вместо работы без лимита с запрошенным вами потолком.',
    'cli.refuse.no_home' => 'этот процесс не может определить ваш домашний каталог ($HOME не задан, $USERPROFILE не задан, и нет записи passwd для его uid), поэтому политика разрешений и цепочка хуков в ~/.candy-code не могут быть найдены. Отказ от запуска вместо чтения из общедоступного каталога — экспортируйте HOME в учётную запись, которой принадлежит эта сессия.',
    'cli.refuse.no_project_root' => 'не удалось определить корень проекта — рабочий каталог процесса недоступен (удалён или нечитаем). Передайте --root <dir>.',
    'cli.refuse.not_searchable' => '{dir} недоступен для поиска этому процессу',
    'cli.refuse.project_settings_unusable' => '{path} не читается для получения permissionRules ({reason}). Отказ от запуска вместо работы с неизвестной политикой разрешений.',
    'cli.refuse.world_writable' => '{path} доступен для записи всем учётным записям на этой машине, поэтому политика разрешений и цепочка хуков в нём — не этого пользователя. Отказ от запуска вместо работы с политикой, которую мог записать кто угодно — `chmod o-w {path}`.',
    'cli.selfupdate.channel_invalid' => '{value}: candy-code self-update --channel принимает stable или dev.',
    'cli.selfupdate.check_available' => 'candy-code: доступно обновление — текущая версия {current}, последняя {latest}. (--check только выводит информацию; ничего не установлено.)',
    'cli.selfupdate.check_unknown' => 'candy-code: не удалось сравнить текущую версию ({current}) с последним релизом ({latest}).',
    'cli.selfupdate.check_up_to_date' => 'candy-code: актуальная версия — текущая {current}, последняя {latest}.',
    'cli.selfupdate.composer_mode' => 'candy-code: self-update заменяет phar-установку, а эта копия установлена через Composer — phar для замены здесь нет. Обновите командой: {command} (для глобальной установки выполните `composer global update sugarcraft/candy-code` вместо этого).',
    'cli.selfupdate.composer_mode_root' => 'candy-code: self-update заменяет phar-установку, а эта копия — пакет sugarcraft/candy-code, установленный как корень Composer — phar для замены здесь нет, и корневой пакет не может обновить себя через собственную команду зависимостей. Обновите командой: {command} (клон забирает новый исходный код, затем пересобирает дерево vendor).',
    'cli.selfupdate.dir_not_writable' => 'candy-code: не удалось заменить phar — каталог {dir} недоступен для записи.',
    'cli.selfupdate.downgrade_refused' => 'candy-code: отказ от понижения версии — текущая {current}, последняя {latest}. (--rollback восстанавливает сохранённую копию; остальное не откатывается.)',
    'cli.selfupdate.download_failed' => 'candy-code: не удалось скачать {asset}: {reason}',
    'cli.selfupdate.empty_download' => 'candy-code: загрузка {asset} не вернула ни одного байта.',
    'cli.selfupdate.fetch_failed' => 'candy-code: не удалось прочитать список релизов: {reason}',
    'cli.selfupdate.flags_exclusive' => '--check только выводит информацию; используйте его отдельно, не вместе с --rollback или --allow-unsigned.',
    'cli.selfupdate.hash_mismatch' => 'candy-code: хеш загруженного phar — {actual}, а не {expected}, подписанный sidecar-файлом. Ничего не заменено.',
    'cli.selfupdate.hash_unreadable' => 'ничего (временный файл не читается)',
    'cli.selfupdate.installed' => 'candy-code: self-update заменил {path} ({from} -> {to}); предыдущий phar сохранён в {old} — `self-update --rollback` восстановит его один раз.',
    'cli.selfupdate.no_dev_release' => 'candy-code: ни один опубликованный dev-релиз (тег {tag}) не содержит одновременно {phar} и {sidecar}.',
    'cli.selfupdate.no_release' => 'candy-code: ни один опубликованный релиз candy-code не содержит одновременно {phar} и {sidecar}.',
    'cli.selfupdate.phar_not_writable' => 'candy-code: не удалось заменить phar — {path} недоступен для записи.',
    'cli.selfupdate.preserve_failed' => 'candy-code: не удалось скопировать запущенный phar в {old}; ничего не заменено.',
    'cli.selfupdate.rename_failed' => 'candy-code: не удалось переместить проверенный phar на место; запущенная копия цела, сохранённая копия осталась в {old}.',
    'cli.selfupdate.rollback_failed' => 'candy-code: не удалось восстановить {old} поверх {path}.',
    'cli.selfupdate.rollback_missing' => 'candy-code: нет сохранённой копии для восстановления: {old} не существует (она появляется только после успешного обновления).',
    'cli.selfupdate.rollback_restored' => 'candy-code: rollback восстановил {old} поверх {path}; сохранённая копия израсходована, это одноразовое восстановление.',
    'cli.selfupdate.sidecar_malformed' => 'candy-code: sidecar {asset} не является sha256 из 64 шестнадцатеричных цифр в нижнем регистре для {phar}. Ничего не заменено.',
    'cli.selfupdate.sidecar_names' => 'candy-code: sidecar указывает на {found}, а не на {phar}. Ничего не заменено.',
    'cli.selfupdate.sig.deprecated' => 'candy-code: этот релиз подписывает сырые байты phar через {asset}; эта устаревшая ветка загружает весь артефакт в память и принимается ещё один цикл релизов. Опубликуйте {replacement} — подпись Ed25519 по телу sha256 sidecar — чтобы проверка никогда не выходила за пределы потока.',
    'cli.selfupdate.sig.sidecar_invalid' => 'candy-code: {asset} не подтверждает sidecar {sidecar} загруженного {phar} по закреплённому ключу релиза. Ничего не заменено.',
    'cli.selfupdate.signature_invalid' => 'candy-code: {asset} не подтверждает загруженный {phar} по закреплённому ключу релиза. Ничего не заменено.',
    'cli.selfupdate.signature_missing' => 'candy-code: этот релиз не содержит ни {asset}, ни {sig_sidecar}, а закреплённый ключ релиза требует его для {phar}. Ничего не заменено (--allow-unsigned — обход только для dev).',
    'cli.selfupdate.staged_windows' => 'candy-code: обновление подготовлено для перезапуска — {new} заменит {path} при завершении этого процесса; ход записывается в {path}.swap.log, сохранённая копия осталась в {old}.',
    'cli.selfupdate.swap_leftover' => 'candy-code: предыдущий self-update оставил подготовленную замену в {new}, которая не была применена (её swap-лог фиксирует прерванные попытки). Этот запуск заменяет подготовку перед обновлением.',
    'cli.selfupdate.swap_spawn_failed' => 'candy-code: не удалось запустить помощник замены; проверенные байты остаются подготовленными в {new}, запущенная копия цела. Выполните переименование в {path} вручную или повторите self-update, когда файл никто не удерживает.',
    'cli.selfupdate.uncomparable' => 'candy-code: текущая версия — {current}, это не релизная версия, которую self-update может упорядочить.',
    'cli.selfupdate.unexpected_operand' => '{operand}: candy-code self-update не принимает операндов.',
    'cli.selfupdate.unsigned_allowed' => 'candy-code: --allow-unsigned пропускает проверку подписи по закреплённому ключу; sha256 sidecar по-прежнему привязан к этим байтам. Обход для dev/тестов — никогда не для релизов.',
    'cli.selfupdate.up_to_date' => 'candy-code: self-update: эта установка уже на последнем релизе ({current}).',
    'cli.selfupdate.usage' => 'Использование: candy-code self-update [--check] [--rollback] [--allow-unsigned] [--channel=stable|dev]',
    'cli.serve.already_running' => 'сервер уже запущен из {dir} — остановите его: candy-code serve stop',
    'cli.serve.already_running_pid' => 'сервер уже запущен из {dir} (pid {pid}, {url}) — остановите его: candy-code serve stop',
    'cli.serve.also' => 'Также: {problems}.',
    'cli.serve.announce.background' => 'candy-code serve: работает в фоне на {url} (pid {pid})',
    'cli.serve.announce.code_detached' => '                   (одноразовый код, действителен {seconds} с; новый: candy-code serve url)',
    'cli.serve.announce.code_foreground' => '                   (одноразовый код, действителен {seconds} с; Ctrl+C останавливает сервер)',
    'cli.serve.announce.listening' => 'candy-code serve: слушает на {url} (pid {pid})',
    'cli.serve.announce.log' => '  лог:             {log}',
    'cli.serve.announce.mode' => '  режим разрешений: {mode}',
    'cli.serve.announce.mode_bypass' => '  режим разрешений: {mode} (клиенты могут выбрать обход)',
    'cli.serve.announce.no_interface' => '                   (адрес интерфейса этой машины не найден: используйте тот, по которому другие машины до неё достают)',
    'cli.serve.announce.remote' => '  !! Открытый HTTP на {host}: токен, код входа и cookie сессии передаются по сети в открытом виде — используйте SSH-туннель или TLS-реверс-прокси (docs/SERVER.md, "Remote access").',
    'cli.serve.announce.root' => '  корень:          {root}',
    'cli.serve.announce.sign_in' => '  вход:            {url}',
    'cli.serve.announce.stop' => '  остановка:       candy-code serve stop',
    'cli.serve.announce.web' => '  веб-интерфейс:   {dir}',
    'cli.serve.announce.web_missing' => '  веб-интерфейс:   не установлен (composer require sugarcraft/candy-code-web)',
    'cli.serve.config.allowed_host_invalid' => 'разрешённый хост `{host}` не является именем хоста или host:port (адрес IPv6 в квадратных скобках)',
    'cli.serve.draining.many' => 'candy-code serve: завершение ({reason}) — ожидание до {seconds} с для {count} активных сессий; повторный сигнал остановит немедленно',
    'cli.serve.draining.one' => 'candy-code serve: завершение ({reason}) — ожидание до {seconds} с для {count} активной сессии; повторный сигнал остановит немедленно',
    'cli.serve.failed_to_start' => 'фоновый сервер не запустился',
    'cli.serve.flag_not_for_action' => 'candy-code serve {action}: {flag} не применим к этому действию',
    'cli.serve.flag_not_for_start' => 'candy-code serve: {flag} не применим к запуску сервера',
    'cli.serve.host_refused' => 'этот сервер не отвечает на хост `{host}`; {fix}',
    'cli.serve.host_refused_fix' => 'запустите с --allowed-host {host} или добавьте в server.allowedHosts',
    'cli.serve.logs.follow_json' => 'candy-code serve logs: -f выводит текст потоком; несовместимо с --output-format json',
    'cli.serve.logs.no_log' => 'нет лога',
    'cli.serve.logs.no_log_at' => 'candy-code serve logs: нет лога в {path} (его пишет только отсоединённый сервер)',
    'cli.serve.no_home' => 'не удалось определить домашний каталог, принадлежащий этому пользователю, для состояния сервера; задайте CANDY_CODE_SERVER_DIR',
    'cli.serve.no_report' => 'фоновый сервер не отчитался в течение {seconds} с; см. {log}',
    'cli.serve.no_report_channel' => 'не удалось создать канал для отчётов фонового сервера',
