    'cmd.mcp-auth.column.server' => 'Сервер',
    'cmd.mcp-auth.column.status' => 'Статус',
    'cmd.mcp-auth.disable.done' => '✓ `{server}` отключён для этой сессии — вызовы отклоняются с следующего хода; список для модели не пересобирается (закон кэша), поэтому его инструменты остаются в перечне до перезапуска.',
    'cmd.mcp-auth.disable.no-client' => 'В этой сессии нет MCP-клиента — нечего отключать (`.mcp.json` не был доверен при запуске).',
    'cmd.mcp-auth.disable.persist-added' => '`{server}` добавлен в пользовательский список disabledMcpServers; он также будет отклонён при запуске.',
    'cmd.mcp-auth.disable.persist-glob' => '! `{server}` содержит спецсимволы fnmatch; --persist записывает только точные имена — сохранённый glob может затронуть серверы, которые эта команда никогда не называла.',
    'cmd.mcp-auth.disable.persist-kept' => '`{server}` уже сохранён в disabledMcpServers.',
    'cmd.mcp-auth.disable.unknown' => '! `{server}` не является объявленным MCP-сервером этой сессии — `/mcp list` показывает имена.',
    'cmd.mcp-auth.disable.usage' => 'Использование: /mcp disable <server> [--persist]',
    'cmd.mcp-auth.empty' => "Нет сохранённых MCP-учётных данных.\n\nУчётные данные нужны только для серверов, требующих OAuth-вход;\nобъявленный http-сервер, которому они не нужны, работает по одному лишь \"url\".\nСами серверы объявляются в \"mcpServers\" в\n<project>/.mcp.json — рецепт: docs/MCP.md, \"{section}\".",
    'cmd.mcp-auth.enable.done' => '✓ `{server}` включён для этой сессии — отклонения сессии снимаются с следующего хода; вызовы снова маршрутизируются только там, где маршрутизация запуска уже допускает это имя.',
    'cmd.mcp-auth.enable.no-client' => 'В этой сессии нет MCP-клиента — нечего включать (`.mcp.json` не был доверен при запуске).',
    'cmd.mcp-auth.enable.not-armed' => '! `{server}` не был отключён для этой сессии.',
    'cmd.mcp-auth.enable.persist-none' => 'Нет записи `{server}` в disabledMcpServers для удаления.',
    'cmd.mcp-auth.enable.persist-removed' => '`{server}` удалён из пользовательского списка disabledMcpServers; запуск больше его не отклоняет.',
    'cmd.mcp-auth.enable.unknown' => '! `{server}` не является объявленным MCP-сервером этой сессии — `/mcp list` показывает имена.',
    'cmd.mcp-auth.enable.usage' => 'Использование: /mcp enable <server> [--persist]',
    'cmd.mcp-auth.failed' => '✗ Регистрация не удалась: {error}',
    'cmd.mcp-auth.heading' => '**MCP-серверы**',
    'cmd.mcp-auth.login-armed' => "↻ Вход MCP начат для `{server}` — ожидание ссылки из браузера.\n\nДочерний процесс привязывает loopback-порт; завершите вход в браузере, пока TUI остаётся отзывчивым. MCP-клиент этой сессии зафиксировал хранилище при запуске, поэтому токен подействует при СЛЕДУЮЩЕМ запуске; `/mcp list` покажет учётные данные после их сохранения.",
    'cmd.mcp-auth.login-busy' => '! Вход для `{server}` уже выполняется — сначала завершите или отмените его (URL и статус в транскрипте выше).',
    'cmd.mcp-auth.login-code-delivered' => '✓ Обратный вызов доставлен ожидающему входу для `{server}` — дочерний процесс завершит обмен, результат появится в транскрипте.',
    'cmd.mcp-auth.login-code-refused' => '! Не удалось доставить обратный вызов входа MCP для `{server}`: {reason}',
    'cmd.mcp-auth.login-code-reason-dial' => "слушатель ожидающего входа не ответил",
    'cmd.mcp-auth.login-code-reason-host' => 'принимаются только loopback-хосты `127.0.0.1` и `localhost`',
    'cmd.mcp-auth.login-code-reason-noslot' => 'вход для этого сервера сейчас не ожидает на этом хосте',
    'cmd.mcp-auth.login-code-reason-port' => 'порт не совпадает с портом обратного вызова, объявленным ожидающим входом',
    'cmd.mcp-auth.login-code-reason-scheme' => 'URL обратного вызова должен использовать схему `http`, к которой привязан слушатель входа',
    'cmd.mcp-auth.login-code-reason-shape' => 'форма: `/mcp login <server> --code <callback-url>` с ровно одним URL',
    'cmd.mcp-auth.login-done' => '✓ Вход MCP для `{server}` завершён (код {code}). Токены подключатся при СЛЕДУЮЩЕМ запуске — начните новую сессию, чтобы разрешение действовало; `/mcp list` обновит панель.',
    'cmd.mcp-auth.login-failed' => <<<'TXT'
✗ Вход MCP для `{server}` завершился с кодом {code} без сохранения токенов.

Последние строки дочернего процесса выше; тот же сценарий в оболочке (`candy-code mcp auth login {server}`) выводит полную ошибку и удобен для отладки проблем с эндпоинтом или портом.
TXT,
    'cmd.mcp-auth.login-failed-spawn' => "✗ Не удалось запустить дочерний процесс входа MCP для `{server}`.\n\nЗапустите форму в оболочке напрямую: `candy-code mcp auth login {server}`.",
    'cmd.mcp-auth.login-guidance' => "Интерактивный вход — команда оболочки, а не ход чата:\n\n  candy-code mcp auth login <server> [token-url] [authorize-url] [registration-url]\n\nЗапускает поток авторизации OAuth с кодом подтверждения и PKCE: браузер\nвозвращает код на loopback-слушатель в оболочке, а сохранённые\nтокены прикрепляются к совпадающим http-серверам при следующем запуске.",
    'cmd.mcp-auth.login-no-entry' => "✗ Не удалось найти собственную точку входа программы для запуска `mcp auth login {server}`.\n\nЗапустите форму оболочки напрямую: `candy-code mcp auth login {server}`.",
    'cmd.mcp-auth.login-served-armed' => "↻ Вход MCP для `{server}` запущен на хосте СЕРВЕРА — ссылка появится ниже; откройте её в браузере на своём устройстве. Браузер не может напрямую обратиться к loopback-слушателю сервера: если откроется страница с ошибкой соединения, скопируйте адрес этой страницы и отправьте `/mcp login {server} --code <that-url>`, чтобы передать обратный вызов ожидающему входу. Токены прикрепятся при СЛЕДУЮЩЕМ запуске; `/mcp list` покажет учётные данные после их сохранения.",
    'cmd.mcp-auth.login-url' => '→ Откройте этот URL для авторизации `{server}`:\n\n  {url}',
    'cmd.mcp-auth.not-found' => '! Учётные данные для `{server}` не найдены.',
    'cmd.mcp-auth.registered' => <<<'TXT'
✓ `{server}` успешно зарегистрирован
Client ID: `{client}`
Запросы к http MCP-серверу с этим точным URL теперь автоматически несут этот токен, обновляемый до истечения срока; серверы, запущенные до этой команды, подхватят его при следующем запуске.
TXT,
    'cmd.mcp-auth.remove-usage' => 'Использование: mcp auth remove <server>',
    'cmd.mcp-auth.reconnect.auth' => '! `{server}` сообщает, что требуется вход через OAuth.',
    'cmd.mcp-auth.reconnect.denied' => '! `{server}` заблокирован шаблоном deny.',
    'cmd.mcp-auth.reconnect.drifted' => "Конфигурация MCP изменилась с момента запуска — переподключение отклонено. Переподключение перезапускает серверы ровно так, как их хранит `.mcp.json` сейчас, тогда как эта сессия была допущена по байтам, которым доверял запуск; запуск смещённых записей поднял бы серверы, которых решения допуска никогда не видели. Перезапустите сессию, чтобы применить изменение; это единственный путь применения.",
    'cmd.mcp-auth.reconnect.error' => 'Запуск не удался: {error}',
    'cmd.mcp-auth.reconnect.heading' => '**Переподключённые MCP-серверы**',
    'cmd.mcp-auth.reconnect.no-client' => 'В этой сессии нет MCP-клиента — переподключать нечего (`.mcp.json` не был доверен при запуске).',
    'cmd.mcp-auth.reconnect.none' => 'для этой сессии серверы не запущены',
    'cmd.mcp-auth.reconnect.refused' => '! `{server}` отклонён при допуске (несовпадение пина доверия или неизвестная запись).',
