    'cmd.mcp-auth.reconnect.state.up' => 'up',
    'cmd.mcp-auth.reconnect.tool-drift' => 'предлагает {now} инструментов; сессия была построена с {was} — список для модели не пересобирается в середине сессии, начните новую сессию, чтобы принять их',
    'cmd.mcp-auth.reconnect.unknown' => 'Эта сессия не записала дайджест запуска для `.mcp.json`, поэтому переподключение не может доказать, что конфигурация всё ещё содержит байты, с которых начал запуск, — отклонено, перезапуск является единственным путём применения.',
    'cmd.mcp-auth.removed' => '✓ Учётные данные для `{server}` удалены',
    'cmd.mcp-auth.status.active' => '● активен',
    'cmd.mcp-auth.status.expired' => '○ истёк',
