    'cmd.mcp-auth.status.none' => '○ нет учётных данных',
    'cmd.mcp-auth.undiscovered' => "! Не удалось обнаружить конечные точки OAuth для `{server}`.\n\nУкажите их явно:\n  `mcp auth add {server}` *<registration-url>* *<token-url>*\n\nНечего обнаруживать обычно означает нечего регистрировать:\nсерверу, не требующему входа, достаточно его \"url\" после\nобъявления в .mcp.json (docs/MCP.md, \"{section}\").",
    'cmd.mcp-auth.unknown' => 'Неизвестная подкоманда \'{sub}\'. Используйте: list, add, remove, login, reconnect, enable, disable',
    'cmd.mcp-auth.usage' => "Использование:\n  mcp auth list                    — список зарегистрированных серверов\n  mcp auth add <server> [reg-url] [token-url]  — сохранить учётные данные OAuth для сервера\n  mcp auth remove <server>         — удалить учётные данные сервера\n  mcp auth login <server>          — вывести команду оболочки для интерактивного входа\n  /mcp reconnect                   — перезапустить объявленные серверы, только если .mcp.json совпадает с запуском\n  /mcp enable <server> [--persist]   — снять отказ этой сессии от объявленного сервера\n  /mcp disable <server> [--persist]  — запретить вызовы объявленного сервера в этой сессии",
