    'sandbox.hook.not_run' => 'Не выполнено: хук `{hook}` ограничен песочницей `{mode}` через sandboxScope, но песочница {name} не может запуститься на этом хосте ({reason}). Ничего не выполнено, ни в песочнице, ни вне её. Сообщите пользователю: он может исправить {name} ({remedy}) или установить bashSandbox в "off".',
    'sandbox.lsp.not_started' => 'Не запущен: языковой сервер `{language}` ({command}) ограничен песочницей `{mode}` через sandboxScope, но песочница {name} не может запуститься на этом хосте ({reason}). Ничего не запущено, ни в песочнице, ни вне её. Сообщите пользователю: он может исправить {name} ({remedy}), установить bashSandbox в "off" или исключить этот сервер с помощью `"sandbox": false` в его записи `lsp`.',
    'sandbox.mcp.not_started' => 'Не запущен: MCP-сервер `{server}` ограничен песочницей `{mode}` через sandboxScope, но песочница {name} не может запуститься на этом хосте ({reason}). Ничего не запущено, ни в песочнице, ни вне её. Сообщите пользователю: он может исправить {name} ({remedy}), установить bashSandbox в "off" или исключить его с помощью `"sandbox": false` в записи пользовательского уровня.',
    'sandbox.mcp.opt_out_ignored' => 'Пропущено: отключение `"sandbox": false` для MCP-сервера(ов) {servers} не из файла пользовательских настроек — только пользовательский уровень может исключить stdio-сервер из песочницы sandboxScope. Сервер(ы) работают в песочнице как ограничено.',
    'sandbox.runner.skipped' => 'Пропущено: запуск {scope} ограничен песочницей `{mode}` через sandboxScope, но песочница {name} не может запуститься на этом хосте ({reason}). Ничего не выполнено, ни в песочнице, ни вне её. Сообщите пользователю: он может исправить {name} ({remedy}) или установить bashSandbox в "off".',
    // ── C-AGT-4.e: cross-session mail (`SendMessage` `to: "session:<id>"`,
    // SessionMailbox drains). Own region for this step; other locales arrive
    // with the i18n carry wave.
    'send.session.sent' => 'В очереди для сессии {target}: она прочитает сообщение, когда будет простаивать (её агент отправил его как {id}). Ожидает как уточняющее направление, а не как указание пользователя.',
    'send.session.subagent' => 'Субагент не может писать в другую сессию; цели `session:` предназначены для агента самой сессии — напишите родителю или сообщите, и пусть родитель говорит за диалог.',
    'send.session.self' => 'Это текущая сессия; вы уже здесь.',
    'send.session.target_invalid' => '"session:{target}" — не id сессии: допустимы только буквы, цифры, точка, подчёркивание и дефис.',
    'send.session.unknown' => 'Сохранённая сессия {target} не найдена — candy-code не может её обнаружить, отправлять нечего.',
    'send.session.background' => 'Сессия {target} — фоновый демон; у демона /bg нет входящих для обработки.',
    'send.session.foreign_root' => 'Сессия {target} относится к другому корню проекта, эта сессия не может ей писать.',
