    'chat.clipboard.clipped' => 'Копия в буфер обмена обрезана до {max} из {chars} символов.',
    'chat.clipboard.no_image' => 'На буфере обмена нет изображения для прикрепления. Ctrl+V читает изображение через pngpaste (macOS), wl-paste (Wayland) или xclip (X11); вставляйте текст клавишей вставки терминала или прикрепите файл через @path.',
    'chat.command.error' => '**Ошибка:** {error}',
    'chat.compact.idle_advisory' => 'Эта сессия простаивает более часа и выросла до ~{tokens} оценочных токенов, превысив контекстное окно в {limit} токенов. Выполните /compact для сжатия контекста перед продолжением. Отправка нового сообщения не будет отправлена как есть: следующий ход превышает порог автокомпакции, поэтому старые обмены сначала суммируются, а ход отклоняется, если этого недостаточно.',
    'chat.compact.idle_auto_scheduled' => 'Автокомпакция при простое: сессия превысила окно простоя с транскриптом выше порога компакции (~{tokens} оценочных токенов при окне в {limit} токенов), поэтому запрос на суммирование отправлен без участия. Свёртка попадёт в следующий ход; ничего не тарифицируется дважды и ответ никому не отправляется.',
    'chat.compact.idle_folded' => 'Компакция во время простоя: ~{before} оценочных токенов стало ~{after}. `compaction.idleAuto` выполнил автоматический уровень, пока сессия простаивала, поэтому сжатые обмены теперь — сводки.',
    'chat.copy.bad_arg' => 'Использование: /copy [n] — n — целое число, отсчитывающее блоки кода от конца последнего ответа; "{arg}" — не число.',
