    'chat.theme.file_malformed' => 'Файл темы \'{file}\' не удалось прочитать ({reason}); отображается как \'{base}\'.',
    'chat.theme.file_missing' => 'Тема \'{theme}\' не является встроенной и не имеет файла в \'{directory}\'; используется тема по умолчанию. Доступны: {available}.',
    'chat.theme.file_notes' => 'Файл темы \'{file}\': {notes}.',
    'chat.theme.file_refused' => 'Тема \'{theme}\' указана в \'{directory}\', но её реальный путь находится вне этой директории, поэтому файл отклонён и не прочитан; используется тема по умолчанию.',
    'chat.theme.set' => 'Тема установлена: \'{theme}\'.',
    'chat.title.error' => '**Ошибка:** {error}',
    'chat.turn.loop_guard' => 'Ход завершён защитой от циклов повторных вызовов: модель вызывала {tool} {count} раз с одинаковыми аргументами и получала одинаковый результат. Ответ выше описывает, где остановка. Укажите другой подход или напишите `continue`, когда что-то изменится.',
    'chat.turn.output_limit' => 'Провайдер остановил этот ответ на лимите вывода, поэтому текст выше может обрываться на полуслове. Увеличьте `maxOutputTokens` в ~/.candy-code/config.json для более длинного ответа или запросите продолжение в следующем сообщении.',
    'chat.turn.steps_exhausted' => 'Ход исчерпал все шаги инструментов до завершения работы, поэтому ответ выше описывает, где остановка — что сделано и что осталось — а не готовый ответ. Напишите `continue` для продолжения или увеличьте лимит для более длинных агентных ходов — флаг --max-turns при запуске приоритетнее настройки `maxToolSteps` в ~/.candy-code/config.json, увеличьте действующий.',
    'chat.turn.unpriced_model' => 'Для модели `{model}` нет цены в приложении, поэтому этот ход тарифицирован как $0.00 — нижняя граница, а не бесплатный вызов — итоги расходов и лимит занижены до появления тарифа. Укажите его в `modelPrices` в ~/.candy-code/config.json (USD за 1M токенов, ключи `input` и `output`).',
    'chat.verbose.failed' => 'Переключение подробного вывода отклонено: {error}',
    'chat.verbose.off' => 'Подробный вывод инструментов выключен — строки снова сворачиваются · только для этой сессии, ничего не записано',
    'chat.verbose.on' => 'Подробный вывод инструментов включён — строки остаются развёрнутыми · только для этой сессии, ничего не записано',
    'chat.verbose.unsavable' => 'Здесь ничего не сохраняет настройки, поэтому переключатель подробного вывода не может измениться',
    'chat.voice.busy' => 'Другая голосовая запись ещё транскрибируется — эта отброшена, ничего не сохранено',
    'chat.voice.recording' => '● запись · Alt+V стоп · Esc отмена',
    'chat.voice.transcribing' => 'транскрибирование…',
    'chat.workflow.cancelled' => '_Рабочий процесс отменён: агенты останавливаются. Отчёт следует._',
    'host.agents.accept.bad_name' => '`{name}` — не имя черновика. Черновик — это один файл непосредственно в директории черновиков, и вы передаёте его имя — строчные буквы, цифры, точки, подчёркивания и дефисы — в /agents accept.',
    'host.agents.accept.exists' => 'Пресет с именем {name} уже существует в {dir}/, и /agents accept никогда не перезаписывает активный пресет. Сначала удалите или переименуйте тот пресет, или создайте черновик через /agents new с другим именем.',
    'host.agents.accept.frontmatter' => 'Черновик {name} не содержит блок frontmatter, разбираемый как отображение, поэтому он не был повышен. Выполните /agents new снова или исправьте файл и примите его ещё раз.',
    'host.agents.accept.missing' => 'Нет черновика с именем {name} в {dir}/. Выполните /agents new для создания черновика или /agents proposed для списка черновиков.',
    'host.agents.accept.mode' => 'Черновик {name} объявляет `permissionMode: {mode}`, что не является одним из режимов этого порта. Укажите один из: {modes} — или опустите ключ для `default`.',
    'host.agents.accept.moved' => 'Черновик {name} теперь в {path} — реестр следующей сессии загрузит его как проектный пресет.',
    'host.agents.accept.policy' => 'Политика, объявленная черновиком (выведена дословно перед перемещением):',
    'host.agents.accept.policy_line' => '  - {key}: {value}',
    'host.agents.accept.self_grant' => '**Внимание:** `{mode}` — это самопредоставление — повышенный пресет начинает запуски с настолько более широкой поверхностью разрешений, чем обычная сессия. Повышение здесь — ваше согласие; сам черновик не мог это предоставить.',
    'host.agents.accept.type' => 'Черновик {name} объявляет `{key}` как значение, которое читатель пресетов не может типизировать — ожидается строка или список строк.',
    'host.agents.accept.unknown' => 'Черновик {name} объявляет `{key}` — ключ, на который не реагирует ни один читатель пресетов{hint}. Удалите его или исправьте написание; /agents accept повышает только файлы, ключи которых читает этот порт.',
    'host.agents.error' => 'Команда /agents draft завершилась ошибкой: {error}',
    'host.agents.new.dispatched' => 'Запрашиваю у агента черновик пресета из этого разговора; он пишет только в слой черновиков, и ничего не повышается, пока вы не выполните /agents accept.',
    'host.agents.proposed.heading' => 'Предложенные черновики агентов:',
    'host.agents.proposed.none' => 'Нет черновиков в {dir}/. Выполните /agents new, чтобы агент создал черновик из этого разговора.',
    'host.agents.usage' => 'Использование: /agents [list|<name>|use <preset|default>|new <focus>|proposed|accept <name>]',
    'host.agents.not_configured' => 'Менеджер агентов не настроен — к этому запуску не подключена среда выполнения субагентов, поэтому /agents не может запускать или отслеживать агентов. Обычный запуск `candy-code` всегда её имеет; сборка с интеграцией в хост должна подключить её.',
    // C-AGT-4.b: the `use` verb. Soft-appended after the block's last row;
    // rows answer `/agent use <preset|default>` and the Alt+A cycle.
    'host.agents.use_default' => 'Возврат к обычному значению по умолчанию для сессии — ничего из того, что сузил предыдущий /agent use, не остаётся применённым.',
    'host.agents.use_switched' => '{name} теперь основной агент этой сессии — его инструменты, модель и минимальный уровень разрешений действуют, пока вы не переключитесь обратно; перезапуск вернёт обычное значение по умолчанию для сессии.',
    'host.agents.use_turn_running' => 'Выполняется ход — основной агент переключается между ходами, как переключатель режима разрешений.',
    'host.agents.use_unavailable' => 'Эта сессия использует обычный эхо-бэкенд; нет ни списка инструментов, ни фильтра, которые основной агент мог бы сузить.',
    'host.agents.use_unknown' => 'Нет пресета списка с именем {name}. Выполните /agents для просмотра списка.',
    'host.bg.active' => 'Активные фоновые сессии: {sessions}',
    'host.bg.backgrounded' => 'Отправлено в фон как {id} (\'{name}\') — используйте /agents для проверки статуса, /bg stop {id} для отмены.',
    'host.bg.default_name' => 'Фоновая задача',
    'host.bg.forked' => 'Разветвлено в фоновую сессию {id} (\'{name}\') — используйте /agents для проверки статуса, /bg stop {id} для отмены.',
    'host.bg.none_active' => 'Нет активных фоновых сессий.',
    'host.bg.not_configured' => 'Фоновые сессии не настроены — этот запуск не может выполнять задачи вне переднего плана. Обычный запуск `candy-code` всегда имеет супервизор; сборка с интеграцией в хост должна подключить его до работы /bg и /fork.',
    'host.bg.start_failed' => 'Не удалось запустить фоновую сессию \'{name}\': {error}',
    'host.bg.stop.already_finished' => 'Фоновая сессия {session} уже завершилась; останавливать нечего.',
    'host.bg.stop.failed' => 'Не удалось остановить фоновую сессию {session}: {error}',
    'host.bg.stop.signalled' => 'Фоновая сессия {session} остановлена (её управляющий сокет отсутствовал, поэтому демон получил сигнал).',
    'host.bg.stop.stopped' => 'Фоновая сессия {session} остановлена.',
    'host.bg.stop.unknown' => 'Нет фоновой сессии {id} в этом запуске — /bg stop показывает активные.',
    'host.bg.stop.unreachable' => 'Не удалось остановить фоновую сессию {session} — демон недоступен или не может быть безопасно сигнализирован.',
    'host.bg.stop_usage' => 'Использование: /bg stop <session-id>',
    'host.bg.usage' => 'Использование: /bg <task>',
    'host.command_shell.bundle_refused' => '[!`{command}` не выполнен: /{name} получен из плагинного бандла — пакета, собранного кем-то другим. Запись бандла отклоняет shell-формы независимо от уровня установки — укажите имя бандла в разделе "trustedBundleCommands" в вашей собственной пользовательской конфигурации, чтобы его shell-формы проходили через шлюз разрешений — остальная часть команды отправлена.]',
    'host.command_shell.mcp_refused' => '[!`{command}` не выполнен: /{name} — это MCP-промпт, полученный с сервера, текст, прибывший по сети. Полученное тело отклоняет shell-формы независимо от доверия проекта — укажите ключ сервера в разделе "mcpPromptShell" в вашей собственной пользовательской конфигурации, чтобы его shell-формы проходили через шлюз разрешений — остальная часть промпта отправлена.]',
    'host.loop.not_configured' => 'Расписания не настроены для этой сессии — /loop не на чём работать. Обычный запуск `candy-code` всегда несёт их; сборка с интеграцией в хост должна их предоставить.',
    'host.loop.usage' => 'Использование: /loop <interval> <prompt> — интервал вида 90s, 15m, 2h, 1d (минимум 10s). Цикл живёт в этом процессе; /schedules показывает его, /schedules delete завершает.',
    'host.loop.bad_interval' => 'Не интервал: {interval}. Используйте секунды (60) или суффикс: 90s, 15m, 2h, 1d.',
    'host.loop.registered' => 'Цикл {name}: каждые {every} — `{prompt}` ставится в очередь как ход (первый запуск через один интервал). Завершается вместе с процессом или /schedules delete {name}.',
    'host.loop.queued' => "Цикл '{name}' наступил: его промпт ставится в очередь для этой сессии.",
    'host.output_style.arity' => '/output-style принимает одно имя стиля или `off`; прочитано как `{args}`.',
    'host.output_style.available' => 'Доступные стили: {names}',
    'host.output_style.cleared' => 'Сейчас ни один стиль вывода не активен — промпт идёт без стилистического свода правил со следующего хода.',
    'host.output_style.column_source' => 'Источник',
    'host.output_style.column_state' => 'Состояние',
    'host.output_style.column_style' => 'Стиль',
    'host.output_style.empty' => "Стили вывода не найдены.\nСтиль — это один markdown-файл в ~/.candy-code/styles/ (или .candy-code/styles/ в проекте),\nназываемый по имени файла: terse.md выбирается командой /output-style terse.",
    'host.output_style.footer' => "/output-style <name> выбирает один стиль; ровно один действует одновременно, и\nпереключение снимает предыдущий. /output-style off очищает слот. `off` —\nзарезервированное слово — файл off.md выбрать нельзя. Стиль, отключённый его\nсобственным frontmatter (`enabled: false`), не попадает в промпт, как бы он ни назывался.",
    'host.output_style.heading' => 'Стили вывода (только для сессии — ничего не записывается в конфигурацию):',
    'host.output_style.matches' => ' (это имя совпадает с {count} файлами стилей — все они действуют)',
    'host.output_style.nothing_active' => 'Ни один стиль вывода не был активен — очищать нечего.',
    'host.output_style.self_disabled' => "\nЕго собственный frontmatter указывает enabled: false, поэтому он не попадает в промпт, пока эта строка не изменится — выбор не может переопределить файл, отключивший себя сам.",
    'host.output_style.set' => "Стиль {name}: АКТИВЕН для этой сессии.{note}\nОн действует в промпте со следующего хода; предыдущий стиль снят — активен ровно один.",
    'host.output_style.state_active' => 'активен',
    'host.output_style.state_off' => 'выключен',
    'host.output_style.state_off_frontmatter' => 'выключен (frontmatter)',
    'host.output_style.unknown' => 'Неизвестный стиль вывода: {name}',
    'host.doctor.heading' => 'Проверки установки (`/doctor`)',
    'host.doctor.column_status' => 'Статус',
    'host.doctor.column_check' => 'Проверка',
    'host.doctor.column_detail' => 'Подробности',
    'host.schedules.not_configured' => 'Расписания не настроены для этой сессии.',
    'host.schedules.usage' => 'Использование: /schedules [list] | add <name> <interval> <prompt> [--mode <mode>] [--provider <name>] [--heartbeat] | enable <name> | disable <name> | delete <name>. Строки хранятся в ~/.candy-code/schedules.json; /schedules add создаёт запись через границы фабрики инструмента Schedule, /loop регистрирует временную.',
    'host.schedules.none' => 'Нет расписаний. /schedules add <name> <interval> <prompt> создаёт запись через те же границы, что и инструмент Schedule, или запишите строку в ~/.candy-code/schedules.json (`name`, `every` в секундах, `prompt`, `root` — каталог проекта, в котором она срабатывает; необязательные `provider`, `permissionMode` (написания класса bypass отклоняются; не указывайте для неинтерактивного минимума), `enabled`, `timeoutSeconds`, `kind` (`task` отвечает, `heartbeat` может молчать)), или /loop для этой сессии. Формат описан в docs/SCHEDULES.md.',
    'host.schedules.row' => '{state}{kind}{name} — каждые {every}, следующий {next} @ {root}: {prompt}',
    'host.schedules.unbound' => 'не привязано',
