    'host.schedules.disabled_loop' => 'Цикл {name} отключён (только для этого процесса — он никогда не был на диске).',
    'host.schedules.deleted' => 'Расписание {name} удалено из schedules.json.',
    'host.schedules.deleted_loop' => 'Цикл {name} удалён (только для этого процесса — он никогда не был на диске).',
    'host.schedules.persist_failed' => 'Расписание {name} изменено в этой сессии, но не может быть записано обратно: {error}',
    'host.schedules.added' => 'Расписание {name}: каждые {every} — `{prompt}` срабатывает в этом проекте как контролируемый фоновый запуск (первый запуск через один интервал, следующий {next}). Создано через фабрику инструмента Schedule: режим зафиксирован при создании, учитывается в лимите моделей на проект, привязано к этому корню. `/schedules delete {name}` удаляет его.',
    'host.schedules.add_usage' => 'Использование: /schedules add <name> <interval> <prompt> [--mode <mode>] [--provider <name>] [--heartbeat]',
