    'host.spend.status_unreported' => 'Расходы: не сообщаются этим провайдером ({cap}). Потоковые ходы и self-hosted провайдеры часто не сообщают об использовании, и сессия без отчёта никогда не отклоняется лимитом.',
    'host.spend.usage' => 'Использование: /budget <amount> — установить лимит расходов сессии (напр. /budget 5 или /budget $2.50), /budget off — снять, /budget без аргумента — показать текущее состояние. Сумма должна быть положительным числом — лимит 0 и отсутствие лимита — противоположные запросы, поэтому `0` отклоняется, а не угадывается, и слишком большое число (`1e309`, т.е. бесконечность) отклоняется, а не принимается как лимит, который никогда не сработает.',
