    'host.turn.command_delegation' => "Команда `/{name}` объявляет {decl}: этот запрос — задача для делегирования, а не для ответа здесь. Вызовите инструмент Task с агентом \"{agent}\"{model} и текстом между ограничителями ниже как его запрос дословно, и ответьте на основе результата этого запуска.\n```\n{prompt}\n```",
