    'host.turn.empty_custom_command' => '{draft} — файл команды, шаблон которого раскрылся в пустоту — чаще всего тело, состоящее только из $ARGUMENTS или $1, вызванное без аргументов. Ничего не отправлено: пустой запрос стоит ход и не сообщает модели ничего. Передайте аргументы или дайте файлу самостоятельное тело.',
