    'host.turn.in_flight_action' => '`{action}` не выполняется во время активного хода — это изменило бы состояние, которое ход собирается записать. Дождитесь завершения хода или нажмите Esc Esc для отмены.',
    'host.turn.in_flight_command' => '{draft} — команда, а команды не выполняются во время активного хода — это переписало бы историю, к которой ход собирается добавить запись. Черновик всё ещё в поле ввода: нажмите Enter снова после завершения хода или Esc Esc для отмены.',
