    // --- fix-tui-interact 2026-10-14 ---
    'tui.picker.notice.slash_filter' => '`{word}` похоже на слэш-команду, а не на фильтр — Enter здесь продолжит лучшее совпадение. Нажмите Escape и введите команду в поле ввода.',
    'tui.app.stop_all_armed' => 'Сейчас будут остановлены все запущенные агенты — нажмите "s" ещё раз в течение 3 с для подтверждения.',

    // --- fix-app-launch 2026-10-14 ---
    'appLaunch.doctor.mbstring_missing' => 'отсутствует — расчёт ширины символов (mb_*) невозможен; переустановите PHP с ext-mbstring',
    'appLaunch.doctor.intl_missing' => 'отсутствует — расчёт ширины графем/IntlChar невозможен; переустановите PHP с ext-intl',
    'appLaunch.notice.policy_changed' => '⚠ config.json или hooks.yaml изменились с последнего запуска. Новые хуки проекта остаются в карантине только на этот запуск — проверьте ~/.candy-code/config.json и hooks.yaml, после чего они будут применены',
    'appLaunch.notice.project_policy_changed' => '⚠ В hooks.yaml доверенного проекта есть записи, которых не было при последнем запуске. Новые хуки проекта остаются в карантине только на этот запуск — проверьте .candy-code/hooks.yaml этого репозитория, после чего они будут применены',
    'appLaunch.notice.bypass_mode' => '⚠ Режим разрешений — bypass-permissions: каждый вызов инструмента выполняется без подтверждения. Измените его через /permissions (TUI), --permission-mode или задайте другой режим разрешений в ~/.candy-code/config.json',
    // C-SEC-7.a: `-p` now defaults to the ASKING mode, so an unattended scripted
    // run that named no mode starts refusing — the launch says so once, and names
    // the one-flag fix. No trailing period — STDERR_LINE_FORMAT adds one
    // (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.headless_default' => 'ℹ -p запускается в режиме разрешений default: автоматический запуск отклоняет каждый вызов инструмента, требующий подтверждения. Передайте --permission-mode (bypass-permissions выполняет всё) для скриптовых запусков',
    // C-SEC-7.e (owner ruling t212, option 3): the implicit autoReview default
    // announces once per session the first time it engages — de-duped by message
    // identity in the launch-notices store, like the bypass banner. Names the
    // opt-out and owns up to the money. No trailing period — STDERR_LINE_FORMAT
    // adds one (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.auto_review_default' => '⚠ autoReview включён по умолчанию для этого запуска: помеченные вызовы auto-mode проверяются title-моделью, и каждая проверка — платный вызов модели. Установите autoReview в false в ~/.candy-code/config.json, чтобы отключить',
    // C-SEC-6.b: names the file, what it added, and what could not be honoured.
    // No trailing period — STDERR_LINE_FORMAT adds one (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.project_narrowing_rules' => '⚠ {file} сузил разрешения этого запуска: сначала загружено {count} правил deny/ask, отброшено {dropped} правил allow — файл проекта не может выдать allow',
    'appLaunch.notice.restricted' => '⚠ --restricted: этот запуск выполняется без инструментов исполнения кода — Bash, PtyRun, Task, Workflow, ShellStop и mcp_call отсутствуют во всех наборах для модели; файловые инструменты остаются в рамках своих путей, и /permissions не вернёт удалённые инструменты',
    'appLaunch.notice.safe_mode' => '⚠ --safe-mode: доверенные корни проектов, бандлы, а также внешние навыки, команды и агенты игнорируются для этого запуска — он ведёт себя так, будто ничего никогда не было доверенным',

    // --- fix-w2-chat 2026-10-14 ---
    'chat.launch.echo_backend' => 'Провайдер не настроен, поэтому эта сессия работает на встроенном офлайн-эхо-бэкенде — ответы эхом возвращаются локально, модель не вызывается. Выполните `candy-code doctor`, чтобы узнать, что нужно провайдеру, затем нажмите Ctrl+P для переключения модели после настройки.',
    'keys.chat.repaint' => 'Очистить экран и перерисовать кадр',
    'keys.unbound' => 'не назначено',

    // --- C-EXT-1 (Claude Code hook dialect) 2026-10-27 ---
    'hooks.notice.advisory' => '⚠ Хук `async` Claude Code `{hook}` завершился с кодом {code}. Хук `async` просит наблюдать за вызовом инструмента, а не блокировать его, поэтому он не может его остановить и вызов продолжился. Сообщение: {reason}',
    'hooks.notice.claude_dialect' => '⚠ Хук Claude Code `{hook}` завершился с кодом {code}, что Claude Code трактует как неблокирующее замечание, а не решение, поэтому вызов инструмента продолжился. Сообщение: {reason}',
    'hooks.notice.said_nothing' => '(ничего в stderr)',
    'hooks.notice.system_message' => '⚠ Хук `{hook}` оставил сообщение: {message}',

    // --- C-EXT-6.c (type: http hooks) 2026-10-30 ---
    // Every row names the hook and scheme://host only: never a path, a query,
    // or any header value, so an Authorization cannot ride out of the process
    // inside its own refusal.
    'hooks.http.deny_bad_url' => 'HTTP-хук `{hook}` настроен с URL, который невозможно использовать ({reason}); отображаемый адрес — {target}. Хук, не способный указать, куда он обращается, не одобрил этот вызов.',
    'hooks.http.deny_scheme' => 'HTTP-хук `{hook}` указывает {target}, что не является http или https URL. candy-code обращается к хукам только по этим двум схемам, и вызов отклонён, а не выполнен через непроверенный транспорт.',
    'hooks.http.deny_credentials' => 'HTTP-хук `{hook}` содержит учётные данные в URL ({target}). Пароль, записанный в URL, попадает в логи и прокси, поэтому здесь он отклонён; передайте его как заголовок, значение которого читает имя из `allowedEnvVars`.',
    'hooks.http.deny_blocked_target' => 'HTTP-хук `{hook}` недоступен: {reason} ({target}). Приватные и link-local адреса отклоняются тем же правилом, что и исходящие запросы, а страж, до которого не дошли, не одобрил этот вызов.',
    'hooks.http.deny_unanswered' => 'HTTP-хук `{hook}` не ответил ({reason}); цель — {target}. Недоступный хук не одобрил этот вызов, поэтому он отклонён.',
    'hooks.http.deny_header_injection' => 'HTTP-хук `{hook}` не может отправить заголовок `{field}`: имя или значение содержит управляющий символ, что является частью кадрирования запроса, а не значением заголовка. Ничего не отправлено на {target}, вызов отклонён.',
    'hooks.http.notice_unanswered' => '⚠ HTTP-хук `{hook}` не ответил ({reason}), поэтому не смог проверить вызов. Запрос был отправлен на {target}.',
    'hooks.http.reason_unreachable' => 'соединение или запрос превысили таймаут хука',
    'hooks.http.reason_oversized' => 'ответ превысил {bytes} байт и не завершился',
    'hooks.http.reason_no_status' => 'в ответе отсутствует строка статуса HTTP',
    'hooks.http.reason_redirect' => 'произошло перенаправление, а хук не следует редиректам',
    'hooks.http.reason_status' => 'ответ не имеет статус 2xx',


    // --- C-EXT-6.d (type: prompt hooks) 2026-10-31 ---
    // Nothing was dialled and nothing was spent when these fire, so no row
    // carries a {target}: the hook either has no backend to be asked on, or
    // the answer it got is not a verdict.
    'hooks.prompt.deny_unanswered' => 'Промпт-хук `{hook}` не ответил ({reason}). Хук, не вернувший вердикт, не одобрил этот вызов, поэтому он отклонён.',
    'hooks.prompt.notice_unanswered' => '⚠ Промпт-хук `{hook}` не ответил ({reason}), поэтому не смог проверить вызов.',
    'hooks.prompt.reason_call_failed' => 'не удалось обратиться к модели',
    'hooks.prompt.reason_empty_verdict' => 'Промпт-хук `{hook}` отклонил этот вызов без указания причины.',
    'hooks.prompt.reason_no_backend' => 'в этом запуске нет бэкенда заголовков для обращения',
    'hooks.prompt.reason_no_prompt' => 'запись содержит пустой промпт для запроса',
    'hooks.prompt.reason_unparseable' => 'ответ не является единственным JSON-объектом с булевым полем `ok`, как требуется',

    // --- settings help (W3-B i18n migration) ---
    'settings.advisorModel.help' => 'Модель, к которой обращается инструмент `Advisor` за вторым мнением; не задана — по умолчанию — инструмент не предлагается вовсе (дешёвой модели-замены нет: смысл в выбранной вами модели).',
    'settings.allowedTools.help' => 'Белый список имён инструментов или масок; не задан — доступны все инструменты.',
    'settings.attribution.help' => '{"commit": "…", "pr": "…"}: трейлер и строка PR, которые требует git-руководство.',
    'settings.autoCommit.help' => 'off, turn (один коммит за ход, сообщение от модели заголовков) или edit (по одному на Write/Edit); /undo откатывает.',
    // C-SEC-7.e (owner ruling t212, option 3): the help states the implicit
    // default, the once-per-session announce, and the paid-call fact.
    'settings.autoReview.help' => 'При auto вызов, помеченный классификатором безопасности (кроме находки безопасности, которая всегда спрашивает), проверяется моделью заголовков, которая разрешает его, спрашивает вас или отклоняет. Включено по умолчанию, если доступна проверяемая модель; запуск, использующий это значение, сообщает об этом один раз; установите false для отказа. Каждая проверка — платный вызов модели.',
    'settings.autoReviewModel.help' => '`provider/model`, на котором работает авто-ревьюер, например `openai/gpt-4.1-mini`; пусто — модель заголовков. Невозможность создать провайдера отключает ревьюер с предупреждением при запуске.',
    'settings.autoReviewScope.help' => 'Что `autoReview` отправляет ревьюеру: `shell` (по умолчанию) — каждая не read-only shell-команда, прошедшая список паттернов; `writes` также проверяет `Edit`, `Write`, `ApplyPatch` и `WebFetch` с ожидающим diff для write-инструментов; `all` проверяет каждый вызов, прошедший список. Любое другое значение ведёт себя как `shell`. Каждая проверка — платный вызов модели.',
    'settings.autoTest.help' => 'После хода, изменившего файл, выполнить `testCommand`; при ошибке вывод возвращается модели, не более 3 раз за ход.',
    'settings.bashInteractiveIdleSeconds.help' => 'Секунд, в течение которых запуск Bash с `interactive: true` может ничего не выводить, прежде чем будет остановлен как ожидающий нажатия клавиши.',
    'settings.bashMaxTimeoutSeconds.help' => 'Максимальный `timeout`, который может запросить команда Bash; большие значения ограничиваются им.',
    'settings.bashSandbox.help' => 'Linux запускает Bash внутри bubblewrap; macOS — внутри профиля Seatbelt через `sandbox-exec` — запись только в рабочем корне (`no-network` также отключает сеть). `allowlist` (Linux) направляет сетевой трафик через egress-прокси запуска, который разрешает только хосты из `sandboxAllowedDomains`: при пустом списке по умолчанию ведёт себя ТОЧНО как `no-network`, пока вы не укажете хосты, и даже после указания не-HTTP-трафик (ssh, порты БД) и неперечисленные хосты блокируются. На macOS `allowlist` применяется как `no-network`. Отклоняет команды, если jail не может запуститься; нераспознанное значение означает `no-network`, никогда `off`.',
    'settings.bashSandboxNestedUserns.help' => 'Установите `true`, чтобы песочничная команда `Bash` могла создать собственное user namespace — это нужно rootless podman, buildah и песочнице Chromium. По умолчанию `false` запускает bubblewrap с `--unshare-user --disable-userns`, блокируя обычный выход из mount jail; на хосте с устаревшим bubblewrap, не поддерживающим эти флаги, jail запускается с базовым набором, и его описание это указывает.',
    'settings.bashTimeoutSeconds.help' => 'Секунд, в течение которых команда Bash может выполняться, если модель не передала `timeout`; никогда выше потолка Bash.',
    'settings.chatToolTimeoutSeconds.help' => 'Бюджет реального времени для пакета вызовов инструментов, который ветвит путь chat-native (провайдер `command`); отстаившиеся убиваются.',
    'settings.claudeMcpArgs.help' => 'Аргументы для этого бинарника; не задано — используется значение транспорта по умолчанию.',
    'settings.claudeMcpBinary.help' => 'Абсолютный путь к бинарнику `claude`, который транспорт claude-mcp может запустить.',
    'settings.claudeMcpEnv.help' => 'Буквальные переменные окружения, передаваемые этому бинарнику.',
    'settings.compaction.autoPercent.help' => 'Доля окна, при которой старые обмены сжимаются автоматически перед отправкой промпта.',
    'settings.compaction.autoTokens.help' => 'Абсолютный предел автоматического уровня и бюджета шагов в ходе. 0 отключает предел.',
    'settings.compaction.blockPercent.help' => 'Доля окна, после которой промпт отклоняется до освобождения места; единственный уровень, который отклоняет.',
    'settings.compaction.blockTokens.help' => 'Абсолютный предел блокирующего уровня; по умолчанию не задан. Задание позволяет пределу отклонять промпты.',
    'settings.compaction.idleAuto.help' => 'Сжимать сессию, превысившую уровень, во время простоя вместо ожидания следующего промпта, используя механизм автоматического уровня (предел расходов и защита от трещины применяются). off: никогда; hour: после полного окна compaction.idleOfferSeconds; cacheTtl: чуть до истечения prompt-cache провайдера — час, когда провайдер отмечает cache breakpoints, около 5 мин для серверных кэшей, никогда, если кэш не сообщается — когда история превышает порог на ступень ниже автоматического уровня, иначе следующий промпт предзаполнит весь разговор без кэша; на 60-секундном тике 5-минутный кэш сжимается примерно при 4 минутах простоя. Стоит фоновый вызов провайдера; требует compaction.idleOfferSeconds больше 0. Булево значение читается: true означает hour, false — off.',
    'settings.compaction.idleOfferSeconds.help' => 'Сессия, превысившая всё контекстное окно и не тронутая столько времени, получает предложение /compact вместо отправки промпта. 0 — никогда не предлагает.',
    'settings.compaction.keepRecent.help' => 'Сколько последних обменов user/assistant сжатие сохраняет полностью.',
    'settings.compaction.mode.help' => 'llm: модель-суммаризатор пишет сводки (эвристика — её запасной вариант); heuristic: локальные однострочные сводки, никогда не вызов модели; off: ничего не сжимается само, /compact по-прежнему работает и блокирующий уровень по-прежнему отклоняет.',
    'settings.compaction.modelTokenCaps.help' => '{"<model>" или "<provider>/<model>": {"reminderTokens", "autoTokens", "blockTokens"}} переопределяет три предела; 0 сбрасывает один.',
    'settings.compaction.refillLimit.help' => 'Сколько автоматических сжатий подряд могут сразу превысить свой уровень, промпт не отправлен, прежде чем следующий промпт будет отклонён вместо повторного сжатия.',
    'settings.compaction.reminderPercent.help' => 'Доля окна, при которой начинается напоминание «consider compacting» и фоновое сжатие впрок; ниже автоматического уровня.',
    'settings.compaction.reminderTokens.help' => 'Абсолютный предел уровня напоминаний: срабатывает при min(percentage, this). 0 отключает предел.',
    'settings.compaction.summaryAssistantChars.help' => 'Ответы ассистента длиннее этого заменяются на "[exchanged information]" в строке эвристической сводки.',
    'settings.compaction.summaryUserChars.help' => 'Символов пользовательского сообщения, которые строка эвристической сводки сохраняет.',
    'settings.compaction.toolOutputChars.help' => 'Символов ассистентской половины сжатого обмена, показываемых модели-суммаризатору.',
    'settings.connectTimeoutSeconds.help' => 'Ограничение на достижение хоста провайдера (DNS, TCP, TLS); не таймаут запроса.',
    'settings.contextPruning.compress.help' => 'manual предлагает Compress только на ходу, начатом с /compress, один вызов; auto предлагает его на каждом ходу, где модель может обрезать.',
    'settings.contextPruning.iterationNudgeThreshold.help' => 'Результатов инструментов с последнего промпта, после которых длинный цикл инструментов получает напоминание обрезать.',
    'settings.contextPruning.maxContextTokens.help' => 'Размер контекста, выше которого последняя строка несёт усиленное напоминание "prune now".',
    'settings.contextPruning.minContextTokens.help' => 'Размер контекста, ниже которого модель никогда не получает напоминание обрезать; не должен превышать размер жёсткого напоминания.',
    'settings.contextPruning.mode.help' => 'auto обрезает заменённые строки в начале каждого хода; manual только по /sweep; off не показывает теги ссылок. /pruning переопределяет для сессии.',
    'settings.contextPruning.nudgeFrequency.help' => 'Новых строк, которые напоминание ждёт после последнего, чтобы не повторяться на каждом шаге.',
    'settings.contextWindow.help' => 'Переопределение окна токенов: число для модели провайдера или {"<model>": tokens}.',
    'settings.debug.commands.help' => 'Выводить каждый отклонённый каталог или файл custom-команды в stderr, а не только однострочный счётчик запуска.',
    'settings.debug.rules.help' => 'Выводить каждый отклонённый каталог или файл правил в stderr.',
    'settings.debug.skills.help' => 'Выводить каждый пропущенный файл навыка и отклонённый каталог навыков в stderr, а не только однострочный счётчик запуска.',
    'settings.debug.stream.help' => 'Выводить строку "onToken observer threw, detaching it" в stderr, когда потоковый приёмник встраивающего приложения падает в середине хода.',
    'settings.diffPreviewRows.help' => 'Строк diff Edit или Write, показываемых в транскрипте перед суммированием остального.',
    'settings.diffStyle.help' => 'Раскладка diff в транскрипте: `auto` рисует ханки бок о бок на широких терминалах (120 колонок и более) и unified в остальных случаях, `unified` всегда одна колонка, `split` всегда две. Тела diff окрашиваются по токенам в любой раскладке; колонка маркеров `+`/`-` сохраняет цвет.',
    'settings.disabledMcpServers.help' => 'Имена серверов или маски в `.mcp.json` (`untrusted_*`), которые никогда не запускаются, не перечисляются и не вызываются для основного агента и каждого субагента.',
    'settings.disabledRules.help' => 'Пакеты правил пользовательского уровня, исключаемые из промпта с первого хода.',
    'settings.disabledSkills.help' => 'Навыки, удалённые из обнаружения; также приоритетнее enabledSkills.',
    'settings.disabledTools.help' => 'Имена инструментов или маски, удалённые из набора инструментов, видимых модели.',
    'settings.doubleEscSeconds.help' => 'Как быстро второй Esc должен последовать за первым, чтобы отменить выполняемый ход.',
    'settings.embeddingModel.help' => 'Модель эмбеддингов для извлечения памяти на каждом ходу; не задана — ранжирование заметок только по ключевым словам.',
    'settings.enabledSkills.help' => 'Навыки, чьи полные тела включаются в системный промпт каждый ход.',
    'settings.env.diffMaxBytes.help' => 'Байт, которые каждая из двух секций git diff сохраняет перед усечением с пометкой.',
    'settings.env.gitDiffAfterWrites.help' => 'После шага, записавшего файлы, показать staged и unstaged git diff в контексте хода.',
    'settings.expandToolOutput.help' => 'Показывать вывод каждого завершённого вызова инструмента полностью в транскрипте; Ctrl+O или клик по-прежнему сворачивают.',
    'settings.extraBody.help' => 'Поля верхнего уровня запроса, добавляемые к каждому запросу провайдера `custom`.',
    'settings.formatCommands.help' => 'Команда форматирования после редактирования по расширению файла ({"php": "vendor/bin/php-cs-fixer fix {file}"}); выполняется до post-edit lint и перезаписывает файл. По умолчанию выключено.',
    'settings.formatAuto.help' => 'Позволить встроенной таблице расширений (gofmt, rustfmt, ruff/black, shfmt, terraform fmt, node_modules prettier проекта) форматировать отредактированный файл, когда `formatCommands` не задаёт команду для его расширения. Явные записи приоритетнее; проекту всё равно нужны `trustedProjectHooks`. По умолчанию выключено.',
    'settings.globMaxMatches.help' => 'Путей, которые один Glob собирает до остановки обхода; предел вывода по-прежнему ограничивает результат.',
    'settings.grepTimeoutSeconds.help' => 'Секунд, в течение которых один поиск Grep может выполняться до принудительной остановки; найденные до дедлайна совпадения возвращаются как частичный результат.',
    'settings.hooksDefaultTimeoutSeconds.help' => 'Секунд, в течение которых запись хука без `timeout:` может выполняться до принудительной остановки и учёта как отказ.',
    'settings.includeGitInstructions.help' => 'Включать ли общие рекомендации Bash-инструмента по коммитам в системный промпт.',
    'settings.instructions.help' => 'Маски файлов, чьё содержимое становится авторитетным текстом системного промпта.',
    'settings.instructions.walkToRoot.help' => 'По желанию: также читать файлы инструкций выше ближайшего маркера .git, до домашней директории включительно (без неё). Только пользовательский уровень; каждое чтение сохраняет ограничение по области и бюджет по размеру.',
    'settings.instructionsExclude.help' => 'Маски файлов инструкций для пропуска, записываемые как отказы; только пользовательский уровень — репозиторий не может заглушить своего оператора. Файлы внутри checkout сопоставляются по относительному пути; предковые и принудительные файлы вне его — по абсолютному пути, поэтому `**/CLAUDE.local.md` достигает и предковых копий.',
    'settings.keybindings.help' => '{"shell.palette": "Ctrl+B"}: привязать ДОПОЛНИТЕЛЬНОЕ сочетание к id привязки (справка /keys их называет) — Ctrl+<key>, Alt+<key>, Shift+<key> или одиночная функциональная клавиша; штатное сочетание продолжает работать. Присутствующее, но непригодное — отклоняет запуск; удалите клавишу для штатных привязок.',
    'settings.layout.help' => 'Манифест доковых панелей; записывается оболочкой при перемещении панелей.',
    'settings.lintCommands.help' => 'Команда lint после редактирования по расширению файла ({"php": "…", "js": false}); `php -l` встроена.',
    'settings.lsp.help' => '{"php": {"command": "intelephense", "args": ["--stdio"]}}: серверы для диагностики после редактирования, схемы Read и инструмент Lsp.',
    'settings.lspAutoDetect.help' => 'Запускать языковой сервер, указанный в отпечатке проекта (composer.json → intelephense, package.json + tsconfig.json → typescript-language-server, pyproject.toml или setup.py → pyright-langserver, go.mod → gopls, Cargo.toml → rust-analyzer), если его бинарный файл доступен в PATH; ручные записи `lsp` имеют приоритет для каждого языка. Запуск сервера выполняет его и код сборки в открытом дереве, поэтому отпечатки запускают серверы только в проектах, которым вы доверяете хуки; недоверенный корень не запускает ни одного и фиксирует пропуск в уведомлениях о запуске.',
    'settings.maxCheckpoints.help' => 'Контрольные точки хода, до которых может вернуться /rewind, на сессию; самые старые удаляются при превышении.',
    'settings.maxCostUsd.help' => 'Отклонять новые итерации, когда расход по данным провайдера за запуск достигнет указанной суммы в USD; не задано — без лимита. /budget меняет его только для текущего запуска.',
    'settings.maxOutputTokens.help' => 'Максимальный объём вывода на запрос; если не задано, переопределение не отправляется и применяется значение по умолчанию провайдера.',
    'settings.maxToolSteps.help' => 'Макс. вызовов провайдера за ход; если не задано — значение по умолчанию движка.',
    'settings.mcp.enabled.help' => 'Запускать MCP-серверы, указанные в .mcp.json доверенного проекта; off не запускает ни одного, и интерфейсы отображают запуск как отключённый.',
    'settings.mcp.lazySchemaTokens.help' => 'Токены схемы, которые один MCP-сервер может объявить до перехода его инструментов к mcp_list/mcp_call; 0 — никогда не переходит.',
    'settings.mcpResultCapBytes.help' => 'Максимум байт, которые один ответ MCP-инструмента может передать модели.',
    'settings.memory.autoConsolidate.help' => 'Сохраняйте устойчивые факты из завершённых ходов в память и сворачивайте журнал сжатия в неё (проход сновидений); каждый — платный вызов.',
    'settings.memory.dreamIntervalSeconds.help' => 'Минимальное время между двумя dream-проходами для одного проекта; каждый проход — оплачиваемый ход только для чтения.',
    'settings.memory.dreamProposeSkills.help' => 'Пусть проход сновидений предлагает навыки в виде черновиков в ~/.candy-code/skills-proposed; ни один не станет активным, пока вы не выполните /skills accept.',
    'settings.memory.entryMaxBytes.help' => 'Строка индекса самой длинной заметки может отображаться усечённой; при превышении лимита заметок пользователя она снижается до него.',
    'settings.memory.projectNoteMaxBytes.help' => 'Самая крупная заметка памяти проекта может быть записана в .candy-code/memory/ репозитория.',
    'settings.memory.promptMaxBytes.help' => 'Бюджет байтов для строк заметок индекса памяти; бюджет пользовательских заметок уменьшается, чтобы уложиться в него.',
    'settings.memory.promptMaxEntries.help' => 'Большинство заметок в индексе памяти запроса, сначала новые; заметки пользователя учитываются в нём.',
    'settings.memory.userMaxBytes.help' => 'Бюджет байтов для строк пользовательского уровня в рамках общего бюджета.',
    'settings.memory.userMaxEntries.help' => 'Большинство ваших межпроектных (пользовательских) заметок выносится в начало, внутри счётчика заметок.',
    'settings.modelPrices.help' => 'USD за 1 млн токенов для каждой модели ({"input": …, "output": …}), для общей суммы расходов и лимита.',
    'settings.models.help' => 'Модель для запуска, для каждого провайдера ({"<provider>": "<model id>"}); если не задано, используется значение по умолчанию провайдера.',
    'settings.mouse.help' => 'Передавать мышь в candy-code (клики, колесо, выделение); off возвращает терминалу его собственный copy-on-select.',
    'settings.mouseClicks.help' => 'Клики и перетаскивания действуют на то, по чему попадают; off сохраняет колесо и игнорирует клики.',
    'settings.notices.transcriptLimit.help' => 'Большинство предупреждений запуска отображаются строками в транскрипте; остальные сводятся в одну строку «и ещё N», а в stderr выводятся все.',
    'settings.notify.help' => 'off, bell (BEL) или osc9 (уведомление рабочего стола): отправляется по завершении хода и когда агент ожидает подтверждения.',
    'settings.paletteMru.help' => 'Сколько недавно использованных строк палитры запоминается и ранжируется первыми; 0 — не запоминать.',
    'settings.parallelToolCalls.help' => 'Параллельно выполнять вызовы инструментов только для чтения за ход.',
    'settings.parallelToolDeadlineSeconds.help' => 'Максимальное время для одного пакета параллельно отправленных вызовов инструментов.',
    'settings.permissionMode.help' => 'Как ограничиваются вызовы инструментов. Никогда не берётся из файла проекта.',
    'settings.permissionRules.help' => 'Упорядоченные правила allow / deny / ask, сопоставляемые с каждым вызовом инструмента. Общий settings.json доверенного проекта может добавлять записи deny / ask — только в сторону сужения.',
    'settings.permissions.autoAllowReadOnly.help' => 'В режимах default и accept-edits выполнять строку Bash, состоящую только из команд только для чтения (ls, cat, grep, git log, …; без перенаправления в файл, без подстановки, cd только внутри проекта), без подтверждения. Проект может только отключить это.',
    'settings.permissions.autoStrikeLimit.help' => 'В режиме auto столько заблокированных вызовов одной категории подряд превращают следующий в вопрос.',
    'settings.permissions.autoTotalLimit.help' => 'В режиме auto: после блокировки указанного числа вызовов в сессии каждый следующий запрос на блокировку будет подтверждаться вручную.',
    'settings.pluginPaths.help' => 'Дополнительные каталоги для поиска пакетов плагинов формата Claude, помимо двух установленных корневых каталогов; значение может указывать на сам пакет или на контейнер с пакетами. Только на уровне пользователя — checkout не может подключать собственные плагины.',
    'settings.promptCache.keepWarm.help' => 'Warm pings allowed per idle stretch; 0 (default) is off. Each ping re-sends an idle session\'s frozen prefix with one instruction row asking for a one-character reply, so the provider refreshes its prompt cache before the TTL lapses and the next prompt does not prefill the whole conversation uncached. It fires only where the cacheTtl fold declined — below its floor or before its hour — on the same tick/alarm the fold watch already runs, never mid-turn, never more than one at a time, never past this count per stretch. These are billed calls to a session nobody is watching; the spend cap still binds. The count lands in /usage under `warm`.',
    'settings.promptCache.help' => 'Указывает, отмечают ли провайдеры `vertex` и `bedrock` точки прерывания кэша промптов.',
    'settings.promptSuggestionHistory.help' => 'Недавние сообщения (каждое обрезано до 2000 символов), в которых отображается вызов prompt-suggestion.',
    'settings.promptSuggestions.help' => 'После каждого хода запросите у title-модели вероятное следующее сообщение и покажите его серым в пустом поле ввода (→ принимает его).',
    'settings.provider.help' => 'С каким LLM-провайдером работает сессия; каждый запрос отправляется на его хост.',
    'settings.providerRetryAttempts.help' => 'Вызовов на запрос к провайдеру при временном сбое (network, 5xx, 408, 429), включая первый; 1 — без повторов.',
    'settings.providerRetryBaseBackoffMs.help' => 'Пауза перед первой повторной попыткой неудачного вызова провайдера; каждая последующая пауза удваивается.',
    'settings.providers.help' => 'Определения провайдеров по имени ({"<name>": {"type": …, "baseUrl": …, "apiKey": …, "model": …}}); каждая запись дополняет значения по умолчанию для данного типа. Только на уровне пользователя: проект никогда не должен менять адрес, на который отправляются ваши учётные данные.',
    'settings.queueMode.help' => 'steer (агент прочитает на следующем шаге), followup (отправляется после хода) или interrupt (остановить ход на следующем шаге, затем отправить). Tab всегда добавляет в очередь.',
    'settings.readMaxBytes.help' => 'Максимум для одного вызова Read; на странице ниже указан типичный размер ответа на чтение.',
    'settings.readPageBytes.help' => 'Объём одной страницы Read в байтах, включая номера строк, как задано в `limit`.',
    'settings.readPageLines.help' => 'Строки, которые возвращает Read, если вызов не указывает `limit`.',
    'settings.reasoningEffort.help' => 'Уровень размышлений передаётся там, где пара его определяет: openai (o-series и gpt-5, не сборки -chat), anthropic и vertex (claude-3-7 и новее; vertex отвечает через оба своих направления — claude и gemini), gemini (2.5 и новее), sglang (передаётся в каждом запросе), bedrock (id claude, как бюджет размышлений), codex и claude-code (названные уровни передаются в CLI); не задан или не распознан — ничего не запрашивается. `/effort` устанавливает и сбрасывает его.',
    'settings.redactToolOutput.help' => 'По умолчанию выключено: устоявшийся вывод инструментов сохраняется в историю и sessions.db в исходном виде. При включении каждый результат инструмента после устояния проходит через тот же редактор, что защищает память и `/share` — распознанные учётные данные заменяются на `[REDACTED]` в сохраняемых данных и в том, что позже передаётся модели (сам инструмент выполняется без изменений). Поля изображений, документов и использования не затрагиваются. `/export` не добавляет собственного редактирования: он выводит ровно то, что сохранено, поэтому всё записанное до включения остаётся в открытом виде.',
    'settings.references.help' => 'Список `[{"path": "…", "name": "…"}]` каталогов вне рабочего пространства, доступных Read, Grep, Glob и Ls только для чтения; каждый указывается в блоке `<env>` с ограниченной картой содержимого. Изоляция рабочего пространства для Write, Edit и Bash не меняется — ссылка никогда не расширяет область записи. Только для пользовательского уровня: клонированный репозиторий не может добавить корень чтения. Отсутствующий путь, путь не к каталогу или путь внутри корня сессии отклоняется при запуске с уведомлением.',
    'settings.repoMap.enabled.help' => 'Поместите карту расположения кода (пакеты и исходные каталоги PSR-4) в системный промпт.',
    'settings.repoMap.maxBytes.help' => 'Бюджет в байтах для каждого из двух разделов карты репозитория; записи сверх него подсчитываются, но не выводятся.',
    'settings.requireReadBeforeWrite.help' => 'Вкл.: `Edit`, `Write` с перезаписью существующего файла и секция `ApplyPatch`, изменяющая, перемещающая или удаляющая файл, — все отклоняются, пока модель не прочитала этот файл в текущей сессии; создание новых файлов никогда не блокируется. Выкл. по умолчанию: файлы, которые модель прочитала, всё равно защищены правилом об изменении на диске.',
    'settings.resumeCostWarnUsd.help' => 'После устаревшего возобновления первый запрос задерживается один раз, если повторная отправка истории оценивается в не менее чем столько долларов без кэша; нажмите Enter ещё раз, чтобы отправить в любом случае, или сначала выполните /compact. 0 отключает задержку.',
    'settings.sandboxAllowedDomains.help' => 'Хосты, до которых может достучаться песочница `allowlist`: обычные имена (`example.com`), шаблоны `*.example.com` и записи `host:port` (по умолчанию: пусто). Используется только когда `bashSandbox` = `allowlist` на Linux; при ПУСТОМ списке `allowlist` ведёт себя ТОЧНО как `no-network`. Исходящий прокси разрешает только HTTP(S) и ничего более — каждый неперечисленный хост получает 403, а не-HTTP трафик (ssh, порты БД) блокируется. Некорректная запись ИГНОРИРУЕТСЯ при применении: опечатка может только сузить разрешение, но не расширить его. Только для пользовательского уровня: клонированный репозиторий не должен создавать дыру в песочнице, в которой он оказался. macOS применяет `allowlist` как `no-network` — ветка с портами loopback — отложенная задача.',
    'settings.sandboxScope.help' => 'Какие команды вне пути инструмента попадают в «песочницу» `bashSandbox`: `hooks`, `lint`, `format`, `test`, `lsp`, `mcp` (по умолчанию: нет). Активно только пока `bashSandbox` не `off` — список указывает, кто делит песочницу, а не существует ли она. Нераспознанная запись трактуется как EVERY scope (строжайший режим, как и нераспознанное значение `bashSandbox`), и аудит настроек это отмечает. Песочница, которую не удалось запустить, отказывает в работе, а не выполняет её без ограничений: скриптовые хуки отклоняются, lint, format и test пропускаются с указанием причины, а изолированный LSP или MCP stdio-сервер не запускается. Записи `lsp` и записи MCP пользовательского уровня поддерживают по-серверное отключение `"sandbox": false`; отключения MCP проектного уровня игнорируются.',
    'settings.screenReader.help' => 'Отображение для пользователей экранных дикторов. Вкл. — приложение убирает оформление, недоступное диктору: спиннер агента фиксируется на одном кадре, рамки из псевдографики, выделение меню инверсией и подобное заменяются обычным текстом и звуковым сигналом, каждая поверхность подчиняется переключателю. Выкл. — обычный «окрашенный» терминал. Ваша личная настройка доступности, как режим vim в черновиках: клонированный проект не может её изменить. Применяется при следующем чтении после сохранения — без перезагрузки.',
    'settings.rules.standingMaxBytes.help' => 'Бюджет в байтах, оформленный и экранированный, для файлов правил, вставляемых целиком в каждый промпт; правило, превышающее лимит, указывается одной строкой-ссылкой.',
    'settings.scrollWheelLines.help' => 'Строк транскрипта на один щелчок колеса прокрутки.',
    'settings.sd.apiKey.help' => 'Ключ Bearer, отправляемый на сервер Stable Diffusion, если он его требует; предпочтительнее использовать форму-заполнитель `${VAR}`, а не литерал.',
    'settings.sd.baseUrl.help' => 'Базовый HTTP URL Stable Diffusion webui, совместимого с AUTOMATIC1111 (`http://127.0.0.1:7860`); промпты, изображения и API-ключ отправляются туда.',
    'settings.sd.defaultModel.help' => 'Запросы генерации id модели начинаются с; если не задано, сервер выбирает сам.',
    'settings.sd.presets.help' => 'Именованные наборы параметров, предлагаемые медиа-формой; структура принадлежит самому медиа-конвейеру и непрозрачна для слоя настроек.',
    'settings.sd.savePattern.help' => 'Шаблон имени файла для сохраняемых медиафайлов; токены `[date]`, `[time]`, `[seed]` и `[number]` подставляются при сохранении.',
    'settings.sd.timeoutSeconds.help' => 'Секунды до отмены запроса генерации; диффузия на слабом GPU обычно занимает минуты.',
    'settings.secretEnvAllowlist.help' => 'Имена переменных, похожие на учётные данные (или glob-шаблоны), хуки Bash, Grep и скриптов по-прежнему наследуют.',
    'settings.server.allowBypass.help' => 'Разрешает ли серверным сессиям запуск в режиме bypass-permissions или dont-ask (то же, что и --allow-bypass).',
    'settings.server.allowedHosts.help' => 'Имена хостов (или host:port), на которые отвечает сервер, помимо имён loopback и собственных адресов, напр. обратного прокси.',
    'settings.server.allowedIps.help' => 'IP-адреса или диапазоны CIDR клиентов, которым разрешено подключение помимо loopback; остальным — отказ 403 до входа. Пусто: фильтр по адресу отсутствует.',
    'settings.server.allowedOrigins.help' => 'Дополнительные origins браузера (http(s)://host[:port]), которые сервер принимает помимо собственного.',
    'settings.server.askTimeoutSeconds.help' => 'Секунды, в течение которых запрос на разрешение ждёт клиента перед отказом; 0 — ждёт бесконечно.',
    'settings.server.browseRoot.help' => 'Каталог server.dirBrowse ограничен (то же, что и --browse-root); если не задан — домашний каталог.',
    'settings.server.dirBrowse.help' => 'Позволяет авторизованным клиентам просматривать имена каталогов в server.browseRoot и запускать сессии в них (то же, что --allow-dir-browse). По умолчанию отключено.',
    'settings.server.clientTools.help' => 'Разрешить клиентам с областью Write регистрировать инструменты через tools.client.register, чтобы модель могла вызывать код, выполняемый в самом клиенте (инструменты client__*). По умолчанию отключено.',
    'settings.server.drainSeconds.help' => 'Секунды ожидания останавливающегося сервера перед отменой текущих ходов; 0 — остановка немедленно.',
    'settings.server.host.help' => 'Адрес привязки `serve`. Любой адрес, кроме loopback, также требует --allow-remote при запуске.',
    'settings.server.maxConcurrentTurns.help' => 'Одновременные ходы сервера во всех сессиях; лишний отклоняется как busy (повторяемо).',
    'settings.server.maxOpenSessions.help' => 'Максимум одновременно открытых сессий на сервере; при превышении наименее давно использованная неактивная сессия освобождается.',
    'settings.server.port.help' => 'Порт `serve`; 0 — выбрать свободный.',
    'settings.server.trustedProxies.help' => 'IP-адреса или CIDR, чьи заголовки X-Forwarded-For / X-Forwarded-Proto сервер считает доверенными.',
    'settings.serviceTier.help' => 'Премиум-канал направляется туда, куда его определяет пара: openai запрашивает `service_tier: "priority"` на обоих эндпоинтах — Chat и Responses, anthropic запрашивает `speed: "fast"` (только для семейства claude-opus-5-5 GA и семейств research-preview claude-opus-5 / claude-opus-4-8, чей обязательный beta header подставляется автоматически); не задано или не распознано — запрос не отправляется. Быстрый режим тарифицируется по премиум-цене, которую не выведет ни одна таблица, привязанная к ключу модели: пока тировая пара активна, её ходы записываются в реестр без цены, никогда — по угаданному тарифу. Применяется при запуске и при каждой пересборке провайдера или модели.',
    'settings.sessionRetentionDays.help' => 'При каждом запуске удаляет безымянные незакреплённые сессии, неактивные более указанного числа дней, и сообщает, какие именно; 0 (по умолчанию) — сохраняет всё.',
    'settings.sessions.autoTitle.help' => 'Называть каждую новую сессию по первому ходу одним вызовом модели заголовков; при выключении сессия остаётся без имени до /rename.',
    'settings.sessions.awayRecap.help' => 'Когда терминал получает фокус обратно после отсутствия три минуты и более, выводится одно резюме о том, на чём остановилась сессия (один вызов модели заголовка на одно отсутствие); off оставляет возврат беззвучным. `/recap` запрашивает резюме в любое время.',
    'settings.skills.listingMaxBytes.help' => 'Бюджет в байтах для всего списка навыков в системном промпте; навыки за его пределами сворачиваются в одну строку «Ещё N навыков».',
    'settings.skills.pathNudges.help' => 'Если инструмент обращается к файлу, покрытому навыком с областью действия по пути, напомнить модели о его существовании — один раз на навык.',
    'settings.statusLine.help' => '{"type": "command", "command": "…", "refreshSeconds": 2}: shell-команда, чей вывод формирует строку состояния, перезапускается каждые refreshSeconds (от 2 до 3600, по умолчанию 2). Она получает сессию как один JSON-документ через stdin (session_id, cwd, model, workspace, version, cost, а также дополнительные поля candy_code); команда, которая никогда не читает stdin, всё равно выполняется.',
    'settings.streamHeaderTimeoutSeconds.help' => 'Секунды, которые подключённый сервер потоковой передачи может потратить на отправку заголовков ответа; не общий таймаут запроса.',
    'settings.streamIdleTimeoutSeconds.help' => 'Секунды ожидания байтов при одном чтении потокового ответа до признания соединения мёртвым; на каждое чтение, не суммарно.',
    'settings.subagentMaxActive.help' => 'Делегированные запуски, которые сессия может выполнять одновременно; учитываются все уровни, участники и фоновые агенты. При превышении лимита вызов `Task` отклоняется. Не задано — по умолчанию — или 0 — без ограничений.',
    'settings.subagentMaxConcurrent.help' => 'Одновременные вызовы `Task` в одном пакете (остальные ждут свободный слот) и ширина каждого пула агентов. Не задано — по умолчанию — или 0 означает отсутствие ограничения.',
    'settings.subagentMaxDepth.help' => 'Уровни ниже сессии, на которых может быть делегированный запуск; запуск на последнем уровне не получает `Task`. 1 запрещает субагентам делегировать дальше.',
    'settings.subagentMaxTurns.help' => 'Лимит шагов для субагента — делегирование `Task`, этап рабочего процесса или запуск `executeAgents`, — чей пресет не объявляет `maxTurns`.',
    'settings.subagentModel.help' => 'Модель, на которой работает делегированный субагент, если его пресет указывает `inherit`; без значения — модель сессии.',
    'settings.summaryModel.help' => 'Модель, создающая сводки сжатия; без значения — модель диалога, переиспользующая кэш промпта.',
    'settings.symbolMap.enabled.help' => 'Поместить ранжированную карту репозитория на уровне символов в системный промпт, снятую один раз за сессию.',
    'settings.temperature.help' => 'Температура сэмплирования, которую провайдер `custom` отправляет, если запрос не указывает её.',
    'settings.terminalBackground.help' => 'Что адаптивная тема предполагает за текстом: auto спрашивает терминал (OSC 11, затем COLORFGBG); light или dark указывают явно.',
    'settings.testCommand.help' => 'Команда оболочки для запуска тестов проекта в корне проекта (`composer test`, `pytest -q`); что выполняет `autoTest`.',
    'settings.theme.help' => 'Цветовая тема; /theme и палитра меняют её на лету. Пользовательские темы загружаются из JSON-файлов в ~/.candy-code/themes.',
    'settings.thinkingBudget.help' => 'Бюджет токенов размышления: `thinkingConfig` Gemini на провайдере `vertex`; расширенное размышление на провайдере `anthropic`, где минимум Messages API — 1024 (0 или без значения — выкл. на любой ветке). Токены размышления тарифицируются как вывод.',
    'settings.titleModel.help' => 'Модель, называющая сессии и создающая подсказки промптов; без значения — дешёвая вспомогательная модель по умолчанию для типа провайдера, до блочной модели.',
    'settings.transcriptJsonl.help' => 'Зеркалировать каждый зафиксированный транскрипт в журнал JSONL только для добавления в `~/.candy-code/transcripts/<project>/` (файлы 0600) и передавать скриптам-хукам ключ stdin `transcript_path`, указывающий на него. Журнал хранит сырой диалог и растёт без ограничений; читается при запуске, поэтому изменение применяется при следующем старте.',
    'settings.toolInstructionCapBytes.help' => 'Максимум байт тела управляющего CLAUDE.md/AGENTS.md, которое результат Edit, Write или ApplyPatch может нести; остальное обрезается с маркером.',
    'settings.toolOutputCapBytes.help' => 'Максимум байт, которые один результат Bash, Grep, Glob, Lsp или WebFetch может передать модели; обрезанное сохраняется в файл, указанный в результате.',
    'settings.toolOutputPreviewLines.help' => 'Строки свёрнутого результата инструмента, показываемые в транскрипте; Ctrl+O разворачивает остальное.',
    'settings.toolSpillCaptureBytes.help' => 'Максимум вывода команды Bash (на поток), хранимый в памяти и сохраняемый в файл-спилл при обрезке результата; никогда ниже лимита вывода.',
    'settings.toolSpillMinCapBytes.help' => 'Минимальный лимит результата, при котором обрезанный результат инструмента сохраняется в файл; ниже него обрезка объявляется, а остальное отбрасывается.',
    'settings.toolSpillWindowPercent.help' => 'Максимальная доля контекстного окна, которую может занять один результат инструмента; сверх неё результат сохраняется в файл, а модели показываются начало и конец.',
    'settings.trustedProjectCommands.help' => 'Корни проектов, чьи слэш-команды могут выполнять shell-блоки !`cmd`.',
    'settings.trustedBundleCommands.label' => 'Доверенные команды бандлов',
    'settings.trustedBundleCommands.help' => 'Имена плагинных бандлов, чьи командные файлы могут выполнять shell-блоки !`cmd`; каждая команда по-прежнему оценивается шлюзом разрешений. Имена совпадают с именем манифеста самого бандла. Только пользовательский уровень; по умолчанию пусто, поэтому команды бандлов не запускают shell.',
    'settings.mcpPromptShell.label' => 'Shell для MCP-промптов',
    'settings.mcpPromptShell.help' => 'Ключи MCP-серверов, чьи тела промптов могут выполнять shell-блоки !`cmd`; каждая команда по-прежнему оценивается шлюзом разрешений. Имена совпадают с ключом, который ваша пользовательская конфигурация даёт серверу. Только пользовательский уровень; по умолчанию пусто, поэтому полученные промпты не запускают shell.',
    'settings.trustedProjectHooks.help' => 'Корни проектов, чьи .candy-code/hooks.yaml могут выполняться.',
    'settings.trustedProjectMcp.help' => 'Корни проектов, чьи серверы .mcp.json могут запускаться.',
    'settings.trustedProjectSettings.help' => 'Корни проектов, чьи .candy-code/settings*.json могут задавать ключи проектного уровня.',
    'settings.turnIdleTimeoutSeconds.help' => 'Секунды, в течение которых активный ход может не показывать прогресса перед остановкой как зависший; время простоя, никогда не общее.',
    'settings.ui.imageRenderMode.help' => 'Как сгенерированные изображения выводятся в терминале; `auto` выбирает лучший протокол, о котором сообщает терминал.',
    'settings.ui.mediaDisplayOverrides.help' => 'Настройки отображения по режимам рендеринга (лимиты размера, запасные варианты); ключи — слова режимов рендеринга, значения — параметры отображения.',
    'settings.vimMode.help' => 'Редактирование NORMAL/INSERT в поле черновика (i a I A o O Esc, h j k l w b e 0 $ x, dd D cc C yy y p P v V, текстовые объекты di" da( ciw, счётчики 3dd d2w): перемещения, изменение, удаление и копирование в NORMAL, посимвольный ввод в INSERT. Режим, а не привязки — никогда не появляется в /keys. Применяется при следующем нажатии клавиши после сохранения.',
    'settings.voice.apiKey.help' => 'Bearer-ключ, отправляемый на endpoint транскрипции, если он требует его; предпочтительнее форма-заполнитель `${VAR}`, а не литерал.',
    'settings.voice.baseUrl.help' => 'Базовый HTTP URL endpoint транскрипции, совместимого с OpenAI (конечный `/v1` сохраняется); записанный фрагмент уходит туда и никуда более. Без значения по умолчанию: голосовой ввод остаётся OFF, пока это не задано на пользовательском уровне.',
    'settings.voice.language.help' => 'Код BCP-47 (`en`, `de`), задающий язык транскрипции принудительно; без значения — endpoint определяет сам.',
    'settings.voice.maxSeconds.help' => 'Жёсткий лимит секунд на одну запись (5-600, по умолчанию 120). Лимит передаётся аргументом рекордера, поэтому осиротевшая запись останавливается сама.',
    'settings.voice.model.help' => 'ID модели, отправляемый с каждым запросом транскрипции; `whisper-1` отвечает на endpoint\'ах, совместимых с OpenAI.',
    'settings.watchFiles.help' => 'Отправлять промпт, когда сохранённый файл содержит комментарий, оканчивающийся на AI! (внести изменение) или AI? (ответить на вопрос); обычные комментарии AI идут как контекст. Опрос при бездействии чата; срабатывают только комментарии, сохранённые после запуска, каждый один раз. Только терминальные сессии: наблюдатель работает в процессе терминала, поэтому сессия, хостимая `candy-code serve`, не следит за файлами.',
    'settings.webFetchMaxBytes.help' => 'Максимум загруженного тела, хранимый в памяти; ограничение памяти, лимит вывода — то, что достигает модели.',
    'settings.webFetchTimeoutSeconds.help' => 'Секунды, в течение которых чтение сокета WebFetch может зависнуть перед сбоем загрузки.',
    'settings.webSearchBackend.help' => 'Какой поисковый сервис запрашивает WebSearch: `searxng` (по умолчанию) отправляет каждый запрос на настроенный `webSearchEndpoint`; `brave`, `tavily` и `exa` обращаются к фиксированному хосту сервиса, и каждому нужен API-ключ в окружении (`BRAVE_SEARCH_API_KEY`, `TAVILY_API_KEY`, `EXA_API_KEY`), без возможности указать другой URL.',
    'settings.webSearchEndpoint.help' => 'URL поиска доверенного экземпляра SearXNG (`https://searx.example.org/search`); каждый запрос WebSearch отправляется туда.',
    'settings.webSearchMaxResults.help' => 'Число результатов в одном дайджесте WebSearch, каждый — заголовок, URL и фрагмент.',
    'settings.webSearchTimeoutSeconds.help' => 'Секунды, которые может занимать один поисковый запрос.',
    'settings.webhooks.help' => 'Карта имён хуков на {secret, prompt, permissionMode?, rate?}; POST /api/hooks/{name} затем вставляет тело (экранированное как недоверенное) в промпт и запускает фоновую сессию. Пусто (по умолчанию) — ничего не монтируется. rate — N доставок в минуту на адрес и на хук в целом. bypass-permissions отклоняется для хуков при запуске; хук без режима работает в более строгом из режима сервера и режима по умолчанию. Строка также может содержать signature: {scheme: "github-sha256"|"hmac-sha256", header?, deliveryHeader?}: тогда маршрут проверяет HMAC-SHA256 сырого тела (sha256=<hex>) с секретом строки через заголовок подписи, вместо секрета в пользовательском заголовке, поскольку GitHub не может отправлять пользовательские заголовки; неудачные подписи попадают в ту же блокировку на хук, а уже виденный id доставки (X-GitHub-Delivery по умолчанию для схемы GitHub; настроенный deliveryHeader для общей) отвечает {"ok": true, "duplicate": true} без запуска второй сессии.',
    'settings.webhooksOut.help' => 'Карта имён endpoint\'ов на {url, secret, events}; events — непустой список из turn.completed, session.ended, permission.asked и schedule.fired. Пусто (по умолчанию) — никакого исходящего трафика. Читается только из пользовательского уровня — конфигурация проекта или бандла не может добавить исходящий endpoint. url должен быть https, или http только если его литеральный хост — localhost или loopback-адрес, и никогда не содержит userinfo; secret не менее 16 символов и подписывает каждую доставку HMAC-SHA256 как X-Candy-Code-Signature (sha256=<hex> по точному телу) в паре с X-Candy-Code-Timestamp. Доставка асинхронна на event loop — диспетчеризация никогда не ждёт ответа: 2-секундная граница соединения и 10-секундный сетевой лимит на POST ограничивают каждую доставку (границы вебхука, не таймаут LLM-запроса), сбои транспорта и ответы 5xx поднимают лестницу повторов 2/8/30 секунд, ответы 4xx и редиректы окончательны с первого раза, поскольку редиректы отклоняются, а не следуются, и ограниченная очередь из 128 доставок в полёте отбрасывает новые диспетчеризации при переполнении, не наращивая память. Читается при запуске; изменение карты вступает в силу после перезапуска.',
    'settings.webhooksOut.refuse' => 'webhooksOut в пользовательской конфигурации непригоден: {reason}. Отказ от запуска вместо доставки на непроверенный endpoint — исправьте карту или удалите ключ, чтобы работать без исходящих вебхуков.',
    // --- end settings help ---

