    // --- session.import (C-SES-7.a: the importer core) ---
    'session.import.notice' => 'Импортирован транскрипт {format} — недоверенный справочный материал: его активность инструментов записана как текст, никогда не воспроизводится.',
    'session.import.refusal.not_readable' => 'import: {path} не является читаемым файлом, ничего не импортировано',
    'session.import.refusal.source_shrank' => 'import: источник содержит меньше строк транскрипта, чем хранил предыдущий импорт; уменьшенный транскрипт отклоняется вместо перезаписи',
    'session.import.refusal.too_large' => 'import: транскрипт занимает {bytes} байт, превышая лимит {max} байт',
    'session.import.refusal.too_many_items' => 'import: транскрипт содержит больше строк, чем лимит {max}',
    'session.import.refusal.unknown_format' => 'import: файл не соответствует транскрипту CandyCode, Claude Code, Codex или OpenCode, ничего не угадано',
    'session.import.refusal.unsupported_shape' => 'import: формат транскрипта не распознан ({detail}); неизвестные форматы отклоняются, никогда не угадываются',
    // --- end session.import ---

